def _creative_qc_validate_job(job):
    """PASS/WARN/FAIL based on real artifact validation, never percentages."""
    contract=_creative_job_output_from_db(job)
    if not contract:
        return "FAIL",{"output":False},"Không có Output Contract."
    ok,reason=_creative_verify_output_contract(contract,job.get("project_id"),job.get("scene_id"))
    if not ok:return "FAIL",{"output":False},reason
    return "PASS",{"output":True,"hash":bool((contract.get("output") or {}).get("sha256"))},"OK"


def _creative_qc_run(project):
    _creative_v3_migrate(); project=_batch_project_name(project); results=[]
    with _batch_db() as db:
        rows=db.execute("SELECT * FROM creative_jobs WHERE project_id=? AND stage IN ('IMAGE','DEPTH','MOTION','POSTPROCESS') AND status='DONE'",(project,)).fetchall()
        for row in rows:
            result,checks,error=_creative_qc_validate_job(row)
            _creative_qc_record(project,row["scene_id"],row["stage"],result,checks,error)
            results.append((row["job_id"],result))
    return results


def _creative_timeline(project):
    """Use existing timeline/SRT/CapCut helpers when present; never create a second queue."""
    candidates=[("timeline",("build_timeline","create_timeline","generate_timeline")),
                ("srt",("build_srt","generate_srt","create_srt")),
                ("capcut",("build_capcut_project","create_capcut_project","export_capcut"))]
    out={}
    for key,names in candidates:
        fn=next((globals().get(n) for n in names if callable(globals().get(n))),None)
        if fn:
            try: out[key]=fn(project)
            except Exception as exc: out[key]={"error":str(exc)}
        else: out[key]={"status":"NOT_CONFIGURED"}
    return out


