def _creative_master_full(project,scenes,requested_engine=CREATIVE_ENGINE_AUTO,start=True):
    """Master Full creates durable jobs and starts the common scheduler only.
    It never calls Flow/Z Image/Depth/Motion linearly.
    """
    project=_batch_project_name(project)
    manifest=_creative_prepare_project(project,scenes,requested_engine)
    _creative_set_control(project,"RUNNING","MASTER FULL")
    if start:
        _creative_start_workers(project,int(os.getenv("VHUNG_CREATIVE_FLOW_WORKERS","2") or 2),"FLOW")
    return manifest


def _creative_hud(project):
    _creative_v3_migrate(); project=_batch_project_name(project)
    if not project:return ""
    _creative_refresh_cooldowns()
    with _batch_db() as db:
        jobs=db.execute("SELECT stage,status,COUNT(*) n FROM creative_jobs WHERE project_id=? GROUP BY stage,status",(project,)).fetchall()
        workers=db.execute("SELECT worker_id,status,account_id,job_id,last_heartbeat FROM creative_workers ORDER BY worker_id").fetchall()
        accounts=db.execute("SELECT account_id,status,usage,quota,cooldown_until,session_health FROM creative_accounts ORDER BY account_id").fetchall()
        caps=db.execute("SELECT * FROM creative_captcha WHERE status='OPEN' AND (job_id IN (SELECT job_id FROM creative_jobs WHERE project_id=?)) ORDER BY detected_at",(project,)).fetchall()
    def status_count(stage,status): return sum(int(r["n"]) for r in jobs if r["stage"]==stage and r["status"]==status)
    lines=[f"<div class='batch-center-card'><b>CREATIVE STUDIO V6</b>",f"<div>PROJECT: <b>{html.escape(project)}</b></div>",f"<div>Điều khiển: <b>{html.escape(_creative_control_state(project))}</b></div>"]
    for st in CREATIVE_JOB_STAGES:
        lines.append(f"<div>{st}: DONE {status_count(st,'DONE')} · RUN {status_count(st,'RUNNING')} · READY {status_count(st,'READY')} · RETRY {status_count(st,'RETRY')} · CAPTCHA {status_count(st,'CAPTCHA')} · FAIL {status_count(st,'FAILED')}</div>")
    lines.append("<hr><div>WORKERS</div>")
    for w in workers:
        lines.append(f"<div>{html.escape(str(w['worker_id']))} · {html.escape(str(w['status']))} · Account {html.escape(str(w['account_id'] or '—'))} · Job {html.escape(str(w['job_id'] or '—'))}</div>")
    lines.append("<hr><div>ACCOUNTS</div>")
    for a in accounts:
        lines.append(f"<div>{html.escape(str(a['account_id']))} · {html.escape(str(a['status']))} · usage={a['usage']} · quota={html.escape(str(a['quota']))} · session={html.escape(str(a['session_health']))}</div>")
    if caps:
        lines.append("<hr><b>⚠ CAPTCHA REQUIRED</b>")
        for c in caps:
            lines.append(f"<div>Account: {html.escape(str(c['account_id']))} · Job: {html.escape(str(c['job_id']))} · Scene: {html.escape(str(c['scene_id']))}</div>")
        lines.append("<div>[ MỞ SESSION ] [ ĐÃ XỬ LÝ CAPTCHA ]</div>")
    lines.append("</div>")
    return "".join(lines)


def _creative_stress_test(project,scene_count=1000):
    """Deterministic DB stress test. It does not call external engines."""
    project=_batch_project_name(project) or "CREATIVE_STRESS_TEST"
    scenes=[{"scene_id":f"SC{i:03d}","prompt":f"Stress scene {i}","media_type":"image"} for i in range(1,int(scene_count)+1)]
    _creative_prepare_project(project,scenes,CREATIVE_ENGINE_AUTO)
    with _batch_db() as db:
        total=db.execute("SELECT COUNT(*) FROM creative_jobs WHERE project_id=?",(project,)).fetchone()[0]
        duplicate_groups=db.execute("SELECT project_id,scene_id,stage,COUNT(*) n FROM creative_jobs WHERE project_id=? GROUP BY project_id,scene_id,stage HAVING n>1",(project,)).fetchall()
    return {"project":project,"scenes":len(scenes),"jobs":int(total),"duplicates":len(duplicate_groups),"pass":len(duplicate_groups)==0}


def _creative_assert_no_duplicate_claim(project):
    _creative_v3_migrate(); project=_batch_project_name(project)
    with _batch_db() as db:
        dup=db.execute("SELECT job_id,COUNT(*) n FROM creative_jobs WHERE project_id=? AND status='RUNNING' GROUP BY job_id HAVING n>1",(project,)).fetchall()
        multi=db.execute("SELECT job_id,COUNT(DISTINCT worker_id) n FROM creative_jobs WHERE project_id=? AND status='RUNNING' GROUP BY job_id HAVING n>1",(project,)).fetchall()
    return not dup and not multi


# Make all V3-V6 state durable at startup. This does not launch workers or browsers.
try:
    _creative_v3_migrate()
except Exception:
    pass


# --- V3/V4/V5/V6 execution overrides (kept in one Job Engine) ---
def _creative_output_contract(job, path, engine, account_id=None, worker_id=None):
    fp=Path(path).expanduser().resolve()
    if not fp.is_file() or fp.stat().st_size<=0: raise FileNotFoundError(str(fp))
    import hashlib
    h=hashlib.sha256()
    with fp.open("rb") as fh:
        for chunk in iter(lambda:fh.read(1024*1024),b""): h.update(chunk)
    width=height=None; kind="file"
    suffix=fp.suffix.lower()
    if suffix in {".png",".jpg",".jpeg",".webp",".bmp"}:
        try:
            from PIL import Image
            with Image.open(fp) as im:
                width,height=im.size; im.verify()
            kind="image"
        except Exception as exc: raise ValueError(f"Output ảnh lỗi/không đọc được: {exc}")
    elif suffix in {".mp4",".mov",".mkv",".webm"}:
        head=fp.read_bytes()[:64]
        if suffix==".mp4" and b"ftyp" not in head: raise ValueError("File video MP4 không có chữ ký ftyp hợp lệ.")
        kind="video"
    return {"contract_version":2,"job_id":job.get("job_id"),"project_id":job.get("project_id"),"scene_id":job.get("scene_id"),"stage":job.get("stage"),"engine":engine,"status":"DONE","output":{"path":str(fp),"kind":kind,"width":width,"height":height,"size":fp.stat().st_size,"sha256":h.hexdigest()},"account_id":account_id,"worker_id":worker_id,"job_metadata":job.get("metadata_json") or {},"created_at":_creative_now()}


def _creative_verify_output_contract(contract, project=None, scene_id=None):
    if not isinstance(contract,dict) or contract.get("status")!="DONE": return False,"Output Contract không hợp lệ."
    out=contract.get("output") or {}; fp=Path(str(out.get("path") or "")).expanduser()
    if not fp.is_file() or fp.stat().st_size<=0:return False,"Output không tồn tại hoặc rỗng."
    if project and str(contract.get("project_id"))!=str(_batch_project_name(project)):return False,"Sai project_id."
    if scene_id and str(contract.get("scene_id"))!=str(scene_id):return False,"Sai scene_id."
    try:
        actual=_creative_output_contract({"job_id":contract.get("job_id"),"project_id":contract.get("project_id"),"scene_id":contract.get("scene_id"),"stage":contract.get("stage")},fp,contract.get("engine"),contract.get("account_id"),contract.get("worker_id"))
        ao=actual["output"]
        if str(ao.get("sha256"))!=str(out.get("sha256")):return False,"Hash output không khớp."
        if int(ao.get("size") or 0)!=int(out.get("size") or 0):return False,"Kích thước file output không khớp."
        for k in ("width","height"):
            if out.get(k) is not None and ao.get(k) is not None and int(out[k])!=int(ao[k]):return False,f"Sai {k} output."
        meta=contract.get("job_metadata") or {}
        if isinstance(meta,str):meta=_creative_load_json(meta,{})
        if meta.get("expected_width") and ao.get("width") and int(meta["expected_width"])!=int(ao["width"]):return False,"Sai chiều rộng yêu cầu."
        if meta.get("expected_height") and ao.get("height") and int(meta["expected_height"])!=int(ao["height"]):return False,"Sai chiều cao yêu cầu."
        return True,"OK"
    except Exception as exc:return False,str(exc)


def _creative_scheduler_dispatch(project):
    project=_batch_project_name(project); _creative_v3_migrate(); _creative_refresh_cooldowns()
    state=_creative_control_state(project)
    _creative_recover_v3(project)
    if state in {"PAUSED","STOPPING","STOPPED"}: return False
    _creative_reconcile_dependencies(project)
    with _batch_db() as db:
        workers=db.execute("SELECT worker_id,worker_type,status FROM creative_workers WHERE status='IDLE' AND stop_requested=0 ORDER BY worker_id").fetchall()
    for w in workers:
        if _creative_control_state(project)!="RUNNING": break
        picked=_creative_scheduler_pick(project)
        if not picked:break
        job=_creative_atomic_claim_job(project,w["worker_id"])
        if job:_creative_dispatch_worker(w["worker_id"],job)
    return True


def _creative_dispatch_worker(worker_id, job):
    """Single worker executor for every stage. No stage-specific queue is created."""
    def runner():
        account_id=None
        try:
            _creative_heartbeat(worker_id,job["job_id"])
            if _creative_worker_stop_requested(worker_id):
                _creative_retry_v3(job["job_id"],"NETWORK_ERROR","STOP trước khi worker bắt đầu.",None,allow_fallback=False)
                _creative_release_worker(worker_id,"IDLE","STOP")
                return
            stage=str(job.get("stage") or "IMAGE").upper()
            if stage=="IMAGE":
                
                force_z = str(job.get("requested_engine") or "AUTO").upper()==CREATIVE_ENGINE_AUTO and bool(job.get("fallback_reason")) and "Z Image" in str(job.get("fallback_reason"))
                if force_z:
                    engine,reason=CREATIVE_ENGINE_ZIMAGE,"Flow retry policy đã chuyển Job sang Z Image."
                else:
                    engine,reason=_creative_choose_engine_for_worker(job.get("requested_engine"))
                if not engine: raise CreativeFlowUnavailable(reason or "Không có Engine khả dụng.")
                # actual_engine is committed only here, after the real worker has selected it.
                _creative_set_actual_engine(job["job_id"],engine,reason)
                if engine==CREATIVE_ENGINE_FLOW:
                    account_id,detail=_creative_claim_account_checked(worker_id,job["job_id"],"GOOGLE_FLOW")
                    if not account_id: raise CreativeAuthError(detail)
                    global _CREATIVE_FLOW_ADAPTER
                    if _CREATIVE_FLOW_ADAPTER is None:_CREATIVE_FLOW_ADAPTER=GoogleFlowAdapter()
                    adapter=_CREATIVE_FLOW_ADAPTER
                else:
                    adapter=_CREATIVE_ZIMAGE_ADAPTER
                contract=adapter.run(dict(job),worker_id,account_id)
            else:
                contract=_creative_stage_worker_run(dict(job),worker_id)
                # _creative_stage_worker_run already marks done; continue to common cleanup.
                _creative_cmd("CREATIVE", "DONE", job=job["job_id"], stage=stage)
                return
            ok,reason=_creative_verify_output_contract(contract,job["project_id"],job["scene_id"])
            if not ok: raise RuntimeError(reason)
            _creative_mark_done(job["job_id"],_creative_json(contract,"{}"),contract.get("engine"))
            if account_id:_creative_quota_update(account_id,usage_delta=1,quota=None,success=True)
            _creative_release_worker(worker_id,"IDLE")
            if account_id:_creative_release_account(account_id,success=True)
            _creative_cmd("CREATIVE","DONE",job=job["job_id"],engine=contract.get("engine"))
        except CreativeCaptchaError as exc:
            if account_id:_creative_record_captcha(account_id,job["job_id"],job["scene_id"],str(exc))
            else:_creative_retry_v3(job["job_id"],"CAPTCHA",str(exc),None)
            _creative_release_worker(worker_id,"IDLE",str(exc))
        except CreativeRateLimited as exc:
            _creative_retry_v3(job["job_id"],"RATE_LIMITED",str(exc),account_id)
            _creative_release_worker(worker_id,"IDLE",str(exc))
        except CreativeQuotaExceeded as exc:
            _creative_retry_v3(job["job_id"],"QUOTA",str(exc),account_id)
            _creative_release_worker(worker_id,"IDLE",str(exc))
        except CreativeAuthError as exc:
            _creative_retry_v3(job["job_id"],"AUTH_ERROR",str(exc),account_id)
            _creative_release_worker(worker_id,"IDLE",str(exc))
        except CreativeInvalidRequest as exc:
            _creative_retry_v3(job["job_id"],"INVALID_REQUEST",str(exc),account_id,allow_fallback=False)
            _creative_release_worker(worker_id,"IDLE",str(exc))
        except CreativeFlowTimeout as exc:
            _creative_retry_v3(job["job_id"],"TIMEOUT",str(exc),account_id)
            _creative_release_worker(worker_id,"IDLE",str(exc))
        except CreativeNetworkError as exc:
            _creative_retry_v3(job["job_id"],"NETWORK_ERROR",str(exc),account_id)
            _creative_release_worker(worker_id,"IDLE",str(exc))
        except CreativeFlowUnavailable as exc:
            _creative_retry_v3(job["job_id"],"FLOW_UNAVAILABLE",str(exc),account_id)
            _creative_release_worker(worker_id,"IDLE",str(exc))
        except Exception as exc:
            _creative_retry_v3(job["job_id"],"NETWORK_ERROR",str(exc),account_id)
            _creative_release_worker(worker_id,"IDLE",str(exc))
        finally:
            if account_id:
                with _batch_db() as db:
                    r=db.execute("SELECT status FROM creative_accounts WHERE account_id=?",(account_id,)).fetchone()
                if r and r[0]=="BUSY":_creative_release_account(account_id,success=False)
    with _CREATIVE_RUNTIME_LOCK:
        old=_CREATIVE_WORKER_THREADS.get(worker_id)
        if old and old.is_alive():return old
        th=threading.Thread(target=runner,name=f"CreativeWorker-{worker_id}",daemon=True)
        _CREATIVE_WORKER_THREADS[worker_id]=th; th.start(); return th




def _flow_run_v6(self,job,worker_id,account_id=None):
    if not account_id:raise CreativeAuthError("Flow Job chưa có Account.")
    _creative_heartbeat(worker_id,job["job_id"])
    try:
        _pw,_browser,page=self._context(account_id)
    except Exception as exc: raise CreativeFlowUnavailable(f"Không mở được Session Flow: {exc}")
    if self._captcha_visible(page):raise CreativeCaptchaError("Google Flow yêu cầu CAPTCHA.")
    meta=_creative_load_json(job.get("metadata_json") or "{}",{})
    prompt=str(meta.get("prompt") or meta.get("image_prompt") or "").strip()
    if not prompt:raise CreativeInvalidRequest("Job Flow không có Prompt.")
    try:
        box=page.get_by_role("textbox").last
        if not box.count():box=page.locator("textarea,[contenteditable='true']").last
        if not box.count():raise CreativeFlowUnavailable("Không tìm thấy ô Prompt Google Flow.")
        box.fill(prompt)
        if self._captcha_visible(page):raise CreativeCaptchaError("Google Flow yêu cầu CAPTCHA.")
        buttons=page.get_by_role("button")
        btn=None
        for label in ("Generate","Create","Run","Tạo","Generate image"):
            try:
                candidate=buttons.filter(has_text=label).last
                if candidate.count() and candidate.is_enabled():btn=candidate;break
            except Exception:pass
        if btn is None:raise CreativeFlowUnavailable("Không tìm thấy nút tạo ảnh Google Flow.")
        _creative_heartbeat(worker_id,job["job_id"])
        try:
            with page.expect_download(timeout=180000) as dl_info:
                btn.click()
            download=dl_info.value
        except Exception as exc:
            if self._captcha_visible(page):raise CreativeCaptchaError("Google Flow yêu cầu CAPTCHA.")
            s=str(exc).lower()
            if "timeout" in s:raise CreativeFlowTimeout("Google Flow chờ Download quá thời gian.")
            raise CreativeFlowUnavailable(f"Google Flow không trả Download: {exc}")
        out_dir=project_dir(job["project_id"])/"Hình ảnh";out_dir.mkdir(parents=True,exist_ok=True)
        out=out_dir/f"{job['scene_id']}.png";download.save_as(str(out))
        return _creative_output_contract(job,out,CREATIVE_ENGINE_FLOW,account_id,worker_id)
    except (CreativeCaptchaError,CreativeInvalidRequest,CreativeFlowUnavailable,CreativeFlowTimeout):raise
    except Exception as exc:
        kind=_flow_classify_exception(exc)
        if kind=="AUTH_ERROR":raise CreativeAuthError(str(exc))
        if kind=="RATE_LIMITED":raise CreativeRateLimited(str(exc))
        if kind=="QUOTA":raise CreativeQuotaExceeded(str(exc))
        if kind=="TIMEOUT":raise CreativeFlowTimeout(str(exc))
        if kind=="NETWORK_ERROR":raise CreativeNetworkError(str(exc))
        raise CreativeFlowUnavailable(str(exc))
GoogleFlowAdapter.run=_flow_run_v6

# Extend Google Flow adapter with a real session health check without bypassing CAPTCHA.
def _flow_health_check(self,account_id):
    try:
        item=self._contexts.get(account_id)
        if not item:return {"ok":False,"detail":"Session chưa mở."}
        _pw,browser,page=item
        if not browser.is_connected():return {"ok":False,"detail":"Browser đã mất kết nối."}
        try: page.url
        except Exception as exc:return {"ok":False,"detail":str(exc)}
        if self._captcha_visible(page):return {"ok":False,"detail":"CAPTCHA đang yêu cầu xử lý."}
        return {"ok":True,"detail":"Session Flow còn hoạt động."}
    except Exception as exc:return {"ok":False,"detail":str(exc)}
GoogleFlowAdapter.health_check=_flow_health_check

# Classify common provider/browser errors without turning CAPTCHA into retry.
def _flow_classify_exception(exc):
    s=str(exc or "").lower()
    if isinstance(exc,CreativeCaptchaError) or "captcha" in s or "verify you are human" in s:return "CAPTCHA"
    if isinstance(exc,CreativeRateLimited) or "rate limit" in s or "too many requests" in s:return "RATE_LIMITED"
    if isinstance(exc,CreativeQuotaExceeded) or "quota" in s:return "QUOTA"
    if isinstance(exc,CreativeAuthError) or "unauthorized" in s or "not logged" in s or "login" in s:return "AUTH_ERROR"
    if isinstance(exc,CreativeInvalidRequest) or "invalid prompt" in s:return "INVALID_REQUEST"
    if isinstance(exc,(CreativeFlowTimeout,TimeoutError)) or "timeout" in s:return "TIMEOUT"
    if "not found" in s or "flow unavailable" in s:return "FLOW_UNAVAILABLE"
    if "connection" in s or "network" in s:return "NETWORK_ERROR"
    return "SERVER_BUSY"

# ============================================================
# BATCH CENTER — persistent job/control plane
# ============================================================
# Batch Center is the persistent control plane for the existing production
# pipeline. It persists jobs in SQLite, reconciles real files, exposes a live
# HUD, and owns its own pause/stop gates. IMAGE uses the verified Z-IMAGE-TURBO
# backend. Other stages are adapter slots: they become DONE only when real
# artifacts exist, never from UI percentages alone.
BATCH_DB_FILE = APP_STATE_DIR / "batch_center.sqlite3"
_BATCH_CENTER_LOCK = threading.RLock()
_BATCH_CENTER_THREAD_LOCK = threading.RLock()
_BATCH_CENTER_THREADS = {}
_BATCH_CENTER_STOP_EVENTS = {}
_BATCH_CENTER_PAUSE_EVENTS = {}

def _batch_db():
    conn = sqlite3.connect(str(BATCH_DB_FILE), timeout=30, check_same_thread=False)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA journal_mode=WAL")
    conn.execute("PRAGMA synchronous=NORMAL")
    return conn

def _batch_db_init():
    APP_STATE_DIR.mkdir(parents=True, exist_ok=True)
    with _batch_db() as db:
        db.executescript("""
        CREATE TABLE IF NOT EXISTS batch_runs (
            project_id TEXT PRIMARY KEY,
            status TEXT NOT NULL DEFAULT 'IDLE',
            workers INTEGER NOT NULL DEFAULT 1,
            created_at TEXT,
            started_at TEXT,
            updated_at TEXT,
            completed_at TEXT,
            current_scene TEXT DEFAULT '',
            current_stage TEXT DEFAULT '',
            last_error TEXT DEFAULT ''
        );
        CREATE TABLE IF NOT EXISTS batch_jobs (
            job_id TEXT PRIMARY KEY,
            project_id TEXT NOT NULL,
            scene_id TEXT NOT NULL,
            stage TEXT NOT NULL,
            status TEXT NOT NULL DEFAULT 'PENDING',
            worker_id TEXT DEFAULT '',
            retry_count INTEGER NOT NULL DEFAULT 0,
            created_at TEXT,
            started_at TEXT,
            completed_at TEXT,
            error TEXT DEFAULT '',
            output TEXT DEFAULT '',
            UNIQUE(project_id, scene_id, stage)
        );
        CREATE INDEX IF NOT EXISTS idx_batch_jobs_project_status
            ON batch_jobs(project_id, status);
        """)
_batch_db_init()

def _batch_now():
    return vietnam_now().isoformat()

def _batch_project_name(project):
    return safe_name(str(project or SETTINGS.get("selected_project", "") or ""))

def _batch_job_id(project, scene_id, stage):
    raw = f"{project}|{scene_id}|{stage}"
    return "JOB-" + hashlib.sha1(raw.encode("utf-8")).hexdigest()[:14].upper()

def _batch_sync_jobs(project, reset=False):
    project = _batch_project_name(project)
    env_ok, env_detail = _creative_environment_check()
    if not env_ok:
        workflow_cmd_log("MASTER", "ENVIRONMENT_BLOCKED", project=project, engine=_selected_image_engine(), detail=env_detail, level="ERROR")
        yield _workflow_progress_card(f"⛔ {env_detail} — Master chưa được phép chạy.", 0, "master")
        return
    workflow_cmd_log("MASTER", "ENVIRONMENT_CONNECTED", project=project, engine=_selected_image_engine(), detail=env_detail)
    scenes = load_manifest(project)
    now = _batch_now()
    if not project or not scenes:
        return 0
    with _batch_db() as db:
        if reset:
            db.execute("DELETE FROM batch_jobs WHERE project_id=?", (project,))
        for scene in scenes:
            sid = str(scene.get("scene_id") or "").strip()
            if not sid:
                continue
            for stage in ("IMAGE", "DEPTH", "MOTION", "POSTPROCESS", "QC"):
                db.execute("""
                    INSERT INTO batch_jobs(job_id,project_id,scene_id,stage,status,created_at)
                    VALUES(?,?,?,?,?,?)
                    ON CONFLICT(project_id,scene_id,stage) DO NOTHING
                """, (_batch_job_id(project,sid,stage),project,sid,stage,"PENDING",now))
        db.execute("""
            INSERT INTO batch_runs(project_id,status,workers,created_at,updated_at)
            VALUES(?,?,?,?,?)
            ON CONFLICT(project_id) DO UPDATE SET updated_at=excluded.updated_at
        """, (project,"IDLE",1,now,now))
    return len(scenes)

def _batch_mark_stage(project, stage, status, scene_id=None, error="", output=""):
    project = _batch_project_name(project)
    if not project:
        return
    now = _batch_now()
    with _batch_db() as db:
        if scene_id:
            db.execute("""
                UPDATE batch_jobs SET status=?, started_at=CASE WHEN ?='RUNNING' AND started_at IS NULL THEN ? ELSE started_at END,
                completed_at=CASE WHEN ? IN ('DONE','FAILED','CANCELLED') THEN ? ELSE completed_at END,
                error=?, output=? WHERE project_id=? AND scene_id=? AND stage=?
            """,(status,status,now,status,now,error[:1500],output[:2000],project,str(scene_id),stage))
        else:
            db.execute("UPDATE batch_jobs SET status=?,error=? WHERE project_id=? AND stage=? AND status IN ('PENDING','QUEUED','RETRY')",
                       (status,error[:1500],project,stage))
        db.execute("UPDATE batch_runs SET updated_at=?,current_scene=?,current_stage=?,last_error=? WHERE project_id=?",
                   (now,str(scene_id or ""),stage,error[:1500],project))

def _batch_counts(project):
    project = _batch_project_name(project)
    _batch_sync_jobs(project)
    counts = {s: {"DONE":0,"RUNNING":0,"PENDING":0,"FAILED":0,"RETRY":0,"CAPTCHA":0,"PAUSED":0,"QUEUED":0,"CANCELLED":0} for s in ("IMAGE","DEPTH","MOTION","POSTPROCESS","QC")}
    with _batch_db() as db:
        rows=db.execute("""
            SELECT stage,status,COUNT(*) n FROM batch_jobs
            WHERE project_id=? GROUP BY stage,status
        """,(project,)).fetchall()
        for r in rows:
            counts.setdefault(r["stage"],{})[r["status"]]=int(r["n"])
    return counts

def _batch_reconcile_files(project):
    """Reconcile persistent job state from real project outputs; never trust UI percentages."""
    project = _batch_project_name(project)
    scenes = load_manifest(project)
    if not scenes:
        return
    image_dir = _project_image_dir(project_dir(project))
    for scene in scenes:
        sid=str(scene.get("scene_id") or "")
        if not sid:
            continue
        fp=image_dir/f"{sid}.png"
        if fp.is_file() and fp.stat().st_size >= 1024:
            try:
                from PIL import Image
                with Image.open(fp) as im: im.verify()
                _batch_mark_stage(project,"IMAGE","DONE",sid,output=str(fp))
                _batch_mark_stage(project,"QC","DONE",sid,output=str(fp))
            except Exception:
                pass

def _batch_html(project):
    project = _batch_project_name(project)
    if not project:
        return "<div class='batch-empty'>Chưa chọn Project.</div>"
    _batch_sync_jobs(project)
    _batch_reconcile_stage_outputs(project)
    counts=_batch_counts(project)
    total=len(load_manifest(project))
    run={}
    with _batch_db() as db:
        row=db.execute("SELECT * FROM batch_runs WHERE project_id=?",(project,)).fetchone()
        run=dict(row) if row else {}
    def n(stage): return int(counts.get(stage,{}).get("DONE",0))
    stages=[("IMAGE","IMAGE"),("DEPTH","DEPTH"),("MOTION","MOTION"),("POSTPROCESS","POSTPROCESS"),("QC","QC")]
    cards=[]
    for key,label in stages:
        done=n(key); pct=int(done/max(1,total)*100)
        cards.append(f"""
        <div class='batch-stage'>
          <div class='batch-stage-head'><span>{label}</span><b>{done}/{total}</b></div>
          <div class='batch-bar'><i style='width:{pct}%'></i></div>
          <small>{pct}%</small>
        </div>""")
    active=sum(v.get("RUNNING",0) for v in counts.values())
    # No Google Flow worker pool is wired into this app build yet. Do not fake
    # ACTIVE/CAPTCHA/COOLDOWN numbers; show the real local batch state.
    captcha=sum(v.get("CAPTCHA",0) for v in counts.values())
    cooldown=0
    current=html.escape(str(run.get("current_scene") or "—"))
    stage=html.escape(str(run.get("current_stage") or "—"))
    status=html.escape(str(run.get("status") or "IDLE"))
    workers=max(1,int(run.get("workers") or 1))
    return f"""
    <div class='batch-center-card'>
      <div class='batch-title'>HƯNG PRO WORKFLOW <span>· BATCH CENTER</span></div>
      <div class='batch-project'>PROJECT: <b>{html.escape(project)}</b></div>
      <div class='batch-queue-title'>JOB QUEUE <b>{total:,} Scenes</b></div>
      <div class='batch-stage-grid'>{''.join(cards)}</div>
      <div class='batch-runtime'>
        <div><span>Workers</span><b>{workers}</b></div>
        <div><span>Flow</span><b>{active} ACTIVE / {captcha} CAPTCHA / {cooldown} COOLDOWN</b></div>
        <div><span>Trạng thái</span><b>{status}</b></div>
      </div>
      <div class='batch-current'>CURRENT · <b>{current}</b> · <b>{stage}</b></div>
    </div>
    """

def _batch_table_html(project):
    project=_batch_project_name(project)
    _batch_sync_jobs(project); _batch_reconcile_stage_outputs(project)
    with _batch_db() as db:
        rows=db.execute("""
          SELECT scene_id,
            MAX(CASE WHEN stage='IMAGE' THEN status END) image,
            MAX(CASE WHEN stage='DEPTH' THEN status END) depth,
            MAX(CASE WHEN stage='MOTION' THEN status END) motion,
            MAX(CASE WHEN stage='POSTPROCESS' THEN status END) postprocess,
            MAX(CASE WHEN stage='QC' THEN status END) qc
          FROM batch_jobs WHERE project_id=? GROUP BY scene_id
          ORDER BY CAST(REPLACE(REPLACE(scene_id,'Scene_',''),'SC','') AS INTEGER), scene_id
          LIMIT 200
        """,(project,)).fetchall()
    def icon(s):
        return {"DONE":"✓","RUNNING":"RUNNING","PENDING":"⏳","FAILED":"⚠","RETRY":"↻","PAUSED":"⏸","CAPTCHA":"⚠"}.get(s or "PENDING","⏳")
    body="".join(
        f"<tr><td>{html.escape(r['scene_id'])}</td><td>{icon(r['image'])}</td><td>{icon(r['depth'])}</td><td>{icon(r['motion'])}</td><td>{icon(r['postprocess'])}</td><td>{icon(r['qc'])}</td></tr>"
        for r in rows
    )
    return f"<div class='batch-table-wrap'><table class='batch-table'><thead><tr><th>Scene</th><th>IMAGE</th><th>DEPTH</th><th>MOTION</th><th>POSTPROCESS</th><th>QC</th></tr></thead><tbody>{body}</tbody></table></div>"


def _batch_stage_output_candidates(project, scene_id, stage):
    """Return known local output candidates for a Batch Center stage.
    These are detections only; no fake completion is written when an output
    contract is not present in the current application.
    """
    root = project_dir(project)
    sid = str(scene_id or "").strip()
    media = _project_media_dir(root)
    export = _project_export_dir(root)
    if stage == "IMAGE":
        return [
            media / "Hình ảnh" / f"{sid}.png",
            media / "Hình ảnh" / f"{sid}.jpg",
            media / "Hình ảnh" / f"{sid}.jpeg",
            media / "Hình ảnh" / f"{sid}.webp",
        ]
    if stage == "DEPTH":
        return [
            media / "Depth" / f"{sid}.png",
            media / "Depth" / f"{sid}.webp",
            media / "Depth" / f"{sid}.exr",
        ]
    if stage == "MOTION":
        return [
            media / "Motion" / f"{sid}.mp4",
            media / "Video" / f"{sid}.mp4",
        ]
    if stage == "POSTPROCESS":
        return [
            export / "Postprocess" / f"{sid}.png",
            export / "Postprocess" / f"{sid}.webp",
        ]
    return []


def _batch_file_ok(path):
    try:
        return Path(path).is_file() and Path(path).stat().st_size >= 1024
    except Exception:
        return False


def _batch_reconcile_stage_outputs(project):
    """Reconcile all stages from real files and real per-image QC.
    Unsupported stages stay PENDING instead of being falsely reported DONE.
    """
    project = _batch_project_name(project)
    scenes = load_manifest(project)
    if not project or not scenes:
        return

    for scene in scenes:
        sid = str(scene.get("scene_id") or "").strip()
        if not sid:
            continue

        # IMAGE is backed by the existing production Z-Image output.
        image_candidates = _batch_stage_output_candidates(project, sid, "IMAGE")
        image_path = next((p for p in image_candidates if _batch_file_ok(p)), None)
        if image_path:
            ok, errors = _per_image_qc(project, scene, image_path)
            if ok:
                _batch_mark_stage(project, "IMAGE", "DONE", sid, output=str(image_path))
                _batch_mark_stage(project, "QC", "DONE", sid, output=str(image_path))
            else:
                _batch_mark_stage(
                    project, "IMAGE", "FAILED", sid,
                    error="; ".join(errors), output=str(image_path)
                )
                _batch_mark_stage(
                    project, "QC", "FAILED", sid,
                    error="; ".join(errors), output=str(image_path)
                )
        else:
            # Do not overwrite a currently running image job.
            with _batch_db() as db:
                db.execute(
                    "UPDATE batch_jobs SET status='PENDING' "
                    "WHERE project_id=? AND scene_id=? AND stage='IMAGE' "
                    "AND status NOT IN ('RUNNING','FAILED','RETRY','CANCELLED')",
                    (project, sid),
                )

        # Optional future/local adapters: only mark DONE if a real artifact exists.
        for stage in ("DEPTH", "MOTION", "POSTPROCESS"):
            candidates = _batch_stage_output_candidates(project, sid, stage)
            artifact = next((p for p in candidates if _batch_file_ok(p)), None)
            if artifact:
                _batch_mark_stage(project, stage, "DONE", sid, output=str(artifact))

    # Never claim Flow/CAPTCHA/Cooldown workers exist when there is no worker backend.
    with _batch_db() as db:
        db.execute(
            "UPDATE batch_jobs SET status='PENDING' "
            "WHERE project_id=? AND status='CAPTCHA'",
            (project,),
        )


def _batch_cleanup_runtime(project):
    project = _batch_project_name(project)
    with _BATCH_CENTER_THREAD_LOCK:
        _BATCH_CENTER_STOP_EVENTS.pop(project, None)
        _BATCH_CENTER_PAUSE_EVENTS.pop(project, None)


def _batch_project_thread_alive(project):
    with _BATCH_CENTER_THREAD_LOCK:
        t = _BATCH_CENTER_THREADS.get(_batch_project_name(project))
        return bool(t and t.is_alive())


def _batch_center_refresh(project):
    return _batch_html(project), _batch_table_html(project)

def _batch_center_set_workers(project, workers):
    project=_batch_project_name(project)
    try: workers=max(1,min(20,int(workers or 1)))
    except Exception: workers=1
    _batch_sync_jobs(project)
    with _batch_db() as db:
        db.execute("UPDATE batch_runs SET workers=?,updated_at=? WHERE project_id=?",(workers,_batch_now(),project))
    return _batch_html(project), f"👷 Đã đặt **{workers} Workers** cho Batch Center."

def _batch_center_start(project, workers):
    project=_batch_project_name(project)
    if not project:
        return _batch_html(project), "⛔ Chưa chọn Project."
    _batch_sync_jobs(project)
    _batch_center_set_workers(project, workers)
    with _BATCH_CENTER_THREAD_LOCK:
        t=_BATCH_CENTER_THREADS.get(project)
        if t and t.is_alive():
            return _batch_html(project), "🟡 Batch Center đang chạy."
        stop_evt=threading.Event(); pause_evt=threading.Event()
        _BATCH_CENTER_STOP_EVENTS[project]=stop_evt
        _BATCH_CENTER_PAUSE_EVENTS[project]=pause_evt
        with _batch_db() as db:
            db.execute("UPDATE batch_runs SET status='RUNNING',started_at=COALESCE(started_at,?),updated_at=?,last_error='' WHERE project_id=?",
                       (_batch_now(),_batch_now(),project))
        def worker():
            try:
                # Current local production backend is GPU-serialized; the worker
                # pool is therefore represented in the queue, while one Z-Image
                # render stream owns the 12GB GPU at a time.
                for pct,status,hud in run_zimage_txt2img_queue(project):
                    if stop_evt.is_set():
                        break
                    if pause_evt.is_set():
                        # The existing Z-Image generator owns its own checkpoint
                        # semantics. Leave completed files untouched and exit;
                        # RESUME starts from the existing valid outputs.
                        break
                    _batch_reconcile_stage_outputs(project)
                    with _batch_db() as db:
                        db.execute(
                            "UPDATE batch_runs SET status='RUNNING',updated_at=? WHERE project_id=?",
                            (_batch_now(),project)
                        )
                _batch_reconcile_stage_outputs(project)
                final_counts=_batch_counts(project)
                total=len(load_manifest(project))
                image_done=int(final_counts["IMAGE"].get("DONE",0))
                if stop_evt.is_set():
                    final_status="STOPPED"
                elif pause_evt.is_set():
                    final_status="PAUSED"
                elif image_done >= total and total:
                    final_status="DONE"
                else:
                    final_status="WAITING"
                with _batch_db() as db:
                    db.execute("UPDATE batch_runs SET status=?,updated_at=?,completed_at=CASE WHEN ? IN ('DONE','STOPPED') THEN ? ELSE completed_at END WHERE project_id=?",
                               (final_status,_batch_now(),final_status,_batch_now(),project))
            except Exception as exc:
                workflow_cmd_log("BATCH","WORKER_FAIL",project=project,error=str(exc)[:1200],level="ERROR")
                with _batch_db() as db:
                    db.execute("UPDATE batch_runs SET status='FAILED',updated_at=?,last_error=? WHERE project_id=?",
                               (_batch_now(),str(exc)[:1500],project))
            finally:
                with _BATCH_CENTER_THREAD_LOCK:
                    _BATCH_CENTER_THREADS.pop(project,None)
        t=threading.Thread(target=worker,name=f"VHUNG-Batch-{project}",daemon=True)
        _BATCH_CENTER_THREADS[project]=t
        t.start()
    workflow_cmd_log("BATCH","START",project=project)
    return _batch_html(project), f"▶ Đã bắt đầu Batch Center cho **{project}**."

def _batch_center_pause(project):
    project=_batch_project_name(project)
    evt=_BATCH_CENTER_PAUSE_EVENTS.get(project)
    if evt:
        evt.set()
    with _batch_db() as db:
        db.execute(
            "UPDATE batch_runs SET status='PAUSED',updated_at=? WHERE project_id=?",
            (_batch_now(), project)
        )
    workflow_cmd_log("BATCH","PAUSE",project=project)
    return _batch_html(project), "⏸ Đã tạm dừng Batch Center. Output/checkpoint đã hoàn thành được giữ nguyên."

def _batch_center_resume(project, workers):
    project=_batch_project_name(project)
    evt=_BATCH_CENTER_PAUSE_EVENTS.get(project)
    if evt:
        evt.clear()
    # Only clear the Batch Center's own gate. Do not clear the global workflow
    # stop flags belonging to Voice/Prompt/Master workflows.
    return _batch_center_start(project,workers)

def _batch_center_stop(project):
    project=_batch_project_name(project)
    evt=_BATCH_CENTER_STOP_EVENTS.get(project)
    if evt:
        evt.set()
    pause=_BATCH_CENTER_PAUSE_EVENTS.get(project)
    if pause:
        pause.set()
    try:
        _diffusion_stop_owned_runtime(
            fast=True,
            status_cb=lambda m: _master_cmd(str(m),'INFO')
        )
    except Exception:
        pass
    with _batch_db() as db:
        db.execute(
            "UPDATE batch_runs SET status='STOPPED',updated_at=?,completed_at=? WHERE project_id=?",
            (_batch_now(),_batch_now(),project)
        )
    workflow_cmd_log("BATCH","STOP",project=project)
    return _batch_html(project), "🛑 Đã dừng Batch Center. Output đã hoàn thành được giữ nguyên."






def _creative_atomic_claim_account(worker_id,job_id,provider=CREATIVE_ENGINE_FLOW):
    _creative_v3_migrate(); now=_creative_now()
    with _batch_db() as db:
        db.execute("BEGIN IMMEDIATE")
        wr=db.execute("SELECT account_id,job_id,status FROM creative_workers WHERE worker_id=?",(worker_id,)).fetchone()
        if not wr or wr["job_id"]!=job_id or wr["status"]!="RUNNING":db.execute("ROLLBACK");return None
        row=db.execute("SELECT account_id FROM creative_accounts WHERE provider=? AND status='ACTIVE' AND (cooldown_until IS NULL OR cooldown_until<=?) ORDER BY COALESCE(last_success,''),updated_at LIMIT 1",(provider,now)).fetchone()
        if not row:db.execute("ROLLBACK");return None
        account_id=row[0]
        cur=db.execute("UPDATE creative_accounts SET status='BUSY',updated_at=? WHERE account_id=? AND provider=? AND status='ACTIVE' AND (cooldown_until IS NULL OR cooldown_until<=?)",(now,account_id,provider,now))
        if cur.rowcount!=1:db.execute("ROLLBACK");return None
        db.execute("UPDATE creative_workers SET account_id=?,updated_at=? WHERE worker_id=? AND status='RUNNING' AND job_id=?",(account_id,now,worker_id,job_id))
        db.execute("UPDATE creative_jobs SET account_id=?,updated_at=? WHERE job_id=? AND status='RUNNING' AND worker_id=? AND account_id IS NULL",(account_id,now,job_id,worker_id))
        db.execute("COMMIT");return account_id

# V5 dependency graph: CLEAN MAX VIP is a first-class stage, still using the same queue.
CREATIVE_JOB_STAGES=("IMAGE","DEPTH","MOTION","POSTPROCESS","CLEAN_MAX_VIP","QC","TIMELINE")

def _creative_stage_dependencies(stage,media_type="image"):
    mt=str(media_type or "image").lower()
    if stage=="IMAGE":return []
    if stage=="DEPTH":return ["IMAGE"]
    if stage=="MOTION":return ["DEPTH"] if mt=="video" else ["IMAGE"]
    if stage=="POSTPROCESS":return ["MOTION"] if mt=="video" else ["IMAGE"]
    if stage=="CLEAN_MAX_VIP":return ["POSTPROCESS"]
    if stage=="QC":return ["CLEAN_MAX_VIP"]
    if stage=="TIMELINE":return ["QC"]
    return []

