# ============================================================
# BATCH CENTER V3-V6 BRIDGE
# ============================================================
# Existing Batch Center buttons now control the Creative Job Engine. There is
# deliberately no second Z Image queue: IMAGE fallback is ZImageAdapter ->
# run_zimage_txt2img_queue().

def _batch_center_start(project, workers):
    project=_batch_project_name(project)
    if not project:return _batch_html(project),"⛔ Chưa chọn Project."
    scenes=load_manifest(project)
    if not scenes:return _batch_html(project),"⛔ Project chưa có Scene manifest."
    try: count=max(1,int(workers or 1))
    except Exception: count=1
    _creative_prepare_project(project,scenes,CREATIVE_ENGINE_AUTO)
    _creative_set_control(project,"RUNNING","START từ Batch Center")
    _creative_start_workers(project,count,"FLOW")
    with _batch_db() as db:
        db.execute("INSERT INTO batch_runs(project_id,status,workers,created_at,started_at,updated_at,last_error) VALUES(?,?,?,?,?,?,?) ON CONFLICT(project_id) DO UPDATE SET status='RUNNING',workers=excluded.workers,started_at=COALESCE(batch_runs.started_at,excluded.started_at),updated_at=excluded.updated_at,last_error=''",
                   (project,"RUNNING",count,_batch_now(),_batch_now(),_batch_now(),""))
    _creative_cmd("BATCH","START",project=project,workers=count)
    return _batch_html(project),f"▶ Đã khởi động Job Engine: {count} worker."


def _batch_center_pause(project):
    project=_batch_project_name(project); _creative_pause(project)
    with _batch_db() as db:db.execute("UPDATE batch_runs SET status='PAUSED',updated_at=? WHERE project_id=?",(_batch_now(),project))
    return _batch_html(project),"⏸ Đã PAUSE. Job đang chạy được phép hoàn thành; Job chờ không bị xóa."


def _batch_center_resume(project,workers):
    project=_batch_project_name(project); _creative_resume(project)
    return _batch_center_start(project,workers)


def _batch_center_stop(project):
    project=_batch_project_name(project); _creative_stop(project)
    with _batch_db() as db:db.execute("UPDATE batch_runs SET status='STOPPING',updated_at=? WHERE project_id=?",(_batch_now(),project))
    return _batch_html(project),"🛑 Đã gửi STOP. Worker đang chạy sẽ kết thúc an toàn/reconcile output trước khi nhả Job."


def _batch_html(project):
    return _creative_hud(project)


def _batch_table_html(project):
    project=_batch_project_name(project); _creative_v3_migrate()
    if not project:return ""
    with _batch_db() as db:
        rows=db.execute("SELECT scene_id,MAX(CASE WHEN stage='IMAGE' THEN status END) image,MAX(CASE WHEN stage='DEPTH' THEN status END) depth,MAX(CASE WHEN stage='MOTION' THEN status END) motion,MAX(CASE WHEN stage='POSTPROCESS' THEN status END) post,MAX(CASE WHEN stage='QC' THEN status END) qc FROM creative_jobs WHERE project_id=? GROUP BY scene_id ORDER BY scene_id",(project,)).fetchall()
    def cell(v):
        v=str(v or "PENDING"); return f"<span>{html.escape(v)}</span>"
    body="".join(f"<tr><td>{html.escape(str(r['scene_id']))}</td><td>{cell(r['image'])}</td><td>{cell(r['depth'])}</td><td>{cell(r['motion'])}</td><td>{cell(r['post'])}</td><td>{cell(r['qc'])}</td></tr>" for r in rows)
    return "<table class='batch-scene-table'><thead><tr><th>SCENE</th><th>IMAGE</th><th>DEPTH</th><th>MOTION</th><th>POSTPROCESS</th><th>QC</th></tr></thead><tbody>"+body+"</tbody></table>"

