def normalize_media_mode(value=None) -> str:
    value = str(value or SETTINGS.get("media_mode", "pure_images") or "pure_images").strip().lower()
    return "mixed_media" if value in {"mixed", "mixed_media", "video", "ảnh + video linh hoạt"} else "pure_images"

def scene_media_hint(text: str):
    raw = str(text or "")
    found = re.findall(r"\[(VIDEO|CLIP|IMAGE|IMG|ẢNH|VIDEO CLIP)\]", raw, flags=re.I)
    hint = None
    if found:
        token = found[0].upper()
        hint = "video" if token in {"VIDEO", "CLIP", "VIDEO CLIP"} else "image"
    cleaned = re.sub(r"\[(?:VIDEO|CLIP|IMAGE|IMG|ẢNH|VIDEO CLIP)\]", "", raw, flags=re.I)
    return hint, re.sub(r"\s{2,}", " ", cleaned).strip()

def scene_media_type(scene: dict, default="image") -> str:
    return "video" if str(scene.get("media_type") or scene.get("type") or default).strip().lower() == "video" else "image"

def save_scenes_snapshot(project: str):
    scenes = load_manifest(project)
    if not scenes:
        return "✕ Chưa có Scene để lưu.", []
    root = project_dir(project)
    write_json(_project_content_dir(root) / "Cảnh" / "saved_manifest.json", {"saved_at": datetime.now().isoformat(), "scenes": scenes})
    return f"💾 Đã lưu **{len(scenes)} Scene** + Prompt hiện tại. Dữ liệu gốc vẫn giữ trong manifest.", prompt_scene_rows(scenes)

def _ui_require_profile_and_start(name):
    """Hard preflight for the ONE-CLICK master path.

    The old callback only validated the profile and left Project/Voice resolution
    to later chained callbacks.  That made a stale Gradio state look like a
    dead 1-click button.  Resolve everything once here, before the first async
    stage, without creating any extra project/folder.
    """
    workflow_cmd_log("MASTER", "PREFLIGHT_START", profile=str(name or ""))
    try:
        profile = require_workflow_profile(name)
        cfg = workflow_profile_snapshot(profile)
    except Exception as exc:
        workflow_cmd_log("MASTER", "PREFLIGHT_FAIL", profile=str(name or ""), error=str(exc)[:800])
        print(f"[VHƯNG PRO MAX {vietnam_now().strftime('%H:%M:%S')}] Kiểm tra cấu hình lỗi | {str(exc)[:800]}", flush=True)
        raise
    project_name = safe_name(SETTINGS.get('selected_project', '') or cfg.get('project') or '')
    project_name, root = _ensure_connected_project_for_run(project_name)
    script_text = str(cfg.get('script') or SETTINGS.get('workflow_script', '') or '').strip()
    if not script_text:
        raise RuntimeError('Project chưa có Kịch bản. Hãy nạp/dán Kịch bản trước khi bấm ⚡ 1 Click.')

    actual_lang = str(cfg.get('language') or SETTINGS.get('selected_language') or 'auto').strip() or 'auto'
    if actual_lang == 'auto':
        actual_lang = detect_script_language(script_text)
    if actual_lang not in LANGUAGE_CATALOG:
        actual_lang = 'en'
    selected_engine = str(cfg.get('engine') or SETTINGS.get('selected_engine') or 'auto').strip() or 'auto'
    resolved_engine = resolve_engine(actual_lang, selected_engine)
    configured_voice = str(cfg.get('voice') or SETTINGS.get('selected_voice') or '').strip()
    effective_voice = configured_voice_value(actual_lang, selected_engine, configured_voice)
    if not effective_voice:
        raise RuntimeError(f'Không resolve được Voice cho {actual_lang} / {resolved_engine}.')

    SETTINGS.update({
        'workflow_profile': profile,
        'selected_project': project_name,
        'selected_project_path': str(root),
        'project_output_dir': str(root),
        'voice_output_dir': str(root),
        'workflow_script': script_text,
        'selected_language': cfg.get('language') or 'auto',
        'selected_engine': selected_engine,
        'selected_voice': effective_voice,
    })
    save_settings()
    clear_script_stop()
    workflow_cmd_log(
        'MASTER', '1CLICK_PREFLIGHT_OK', project=project_name,
        profile=profile, language=actual_lang, engine=resolved_engine, voice=effective_voice
    )
    return None

