def _auto_clean_after_qc_ui(project_name, final_qc_text):
    """Compatibility wrapper for the existing QC -> CLEAN UI chain.
    The actual metadata-only implementation is _production_image_cleanup_pipeline().
    """
    project_name = safe_name(str(project_name or SETTINGS.get("selected_project", "Project_001") or "Project_001"))
    final_qc_text = str(final_qc_text or "")
    if not final_qc_text.startswith("✓ FINAL QC PASS"):
        msg = "⛔ CLEAN BỊ KHÓA — Final QC chưa PASS."
        yield msg, [], _workflow_progress_card(msg, 100, "qc")
        return
    emitted = False
    for item in _production_image_cleanup_pipeline(project_name):
        if isinstance(item, (tuple, list)) and len(item) == 3:
            emitted = True
            yield tuple(item)
    if not emitted:
        msg = "🔴 CLEAN không trả đủ 3 output."
        yield msg, [], _workflow_progress_card(msg, 100, "qc")

def _combine_full_voice_final(project, output_dir="", stop_event=None):
    """Consume the combine generator and return ONLY its final 4 outputs.
    This avoids Gradio 6 treating a nested generator object as one output in .then().
    """
    last = None
    for item in combine_full_voice(project, output_dir, stop_event=stop_event):
        last = item
    if last is None:
        raise RuntimeError("Gộp Voice Full không trả kết quả.")
    return last

def _master_clean_stage_if_qc_ok(project_name,final_qc_text,zimage_status):
    status=str(zimage_status or ''); final_text=str(final_qc_text or '').strip()
    if 'MASTER_ZIMAGE_OK' not in status or not final_text.startswith('✓ FINAL QC PASS'):
        msg='⛔ CLEAN BỊ KHÓA — chưa có Z-Image-Turbo hoàn tất + Final QC PASS.'; workflow_cmd_log('MASTER','CLEAN_BLOCKED_MASTER_GATE',project=safe_name(project_name or ''),zimage_ok=('MASTER_ZIMAGE_OK' in status),final_qc=bool(final_text)); yield msg,[],_workflow_progress_card(msg,100,'qc'); return
    state = _load_project_workflow_state(project_name)
    if state.get("clean") == "verified":
        files = _master_gradio_files(_wm_image_files(project_name))
        msg = f"♻ RESUME — CLEAN MAX VIP đã VERIFY trước đó. Bỏ qua làm sạch lại {len(files)} ảnh."
        workflow_cmd_log("MASTER", "RESUME_SKIP_CLEAN", project=project_name, image_count=len(files))
        # Preserve the Z-Image completion gate for the final MASTER callback.
        yield _clean_max_vip_hud(100, msg), files, msg + "\n\n[MASTER_ZIMAGE_OK]"
        return
    # CLEAN must not erase the upstream Z-Image gate stored in the shared
    # workflow_return_status. Re-attach it to the third output consumed by
    # _master_finish_if_qc_ok.
    for clean_item in _auto_clean_after_qc_ui(project_name,final_text):
        if isinstance(clean_item,(tuple,list)) and len(clean_item)==3:
            clean_hud, clean_files, clean_msg = clean_item
            yield clean_hud, clean_files, str(clean_msg or '') + "\n\n[MASTER_ZIMAGE_OK]"
        else:
            yield clean_item

def _master_combine_full_voice_ui(project, output_dir=""):
    if not _master_scene_gate_ok(project):
        msg = "⛔ Gộp Voice bị khóa — Scene Split chưa VERIFY."
        workflow_cmd_log("MASTER", "VOICE_COMBINE_BLOCKED_SCENE_GATE", project=project)
        return None, msg, None, None, msg
    if _master_is_stopped():
        return None, "⏹ MASTER đã dừng — bỏ qua Gộp Voice Full.", None, None, "⏹ MASTER đã dừng."
    workflow_cmd_log("VOICE_FULL", "START", project=project)
