    try:
        data["voice_speed"] = max(0.75, min(1.5, float(data.get("voice_speed", 1.0) or 1.0)))
    except Exception:
        data["voice_speed"] = 1.0
    data["voice_pause_ms"] = max(0, min(1200, _safe_int(data.get("voice_pause_ms", 180), 180, 0, 1200))) if "_safe_int" in globals() else max(0, min(1200, int(float(data.get("voice_pause_ms", 180) or 180))))
    try:
        data["max_vram_percent"] = max(50, min(95, int(data.get("max_vram_percent", 82))))
    except Exception:
        data["max_vram_percent"] = 82
    # Physically remove legacy workflow/profile fields from settings.json.
    # This is a one-time storage migration: workflow config now lives only in
    # LocalAIStudio_Data/workflow_config.json.
    legacy_workflow_keys = {
        "workflow_profiles", "workflow_profile", "selected_language", "selected_engine",
        "selected_voice", "selected_profile", "project_output_dir", "selected_project_path",
        "selected_project", "scene_target_chars", "media_mode", "voice_speed", "voice_pause_ms",
        "gemini_visual_directive_mode", "gemini_reference_images", "gemini_competitor_urls",
        "voice_output_dir",
    }
    if isinstance(saved, dict) and any(k in saved for k in legacy_workflow_keys):
        try:
            cleaned_saved = {k: v for k, v in saved.items() if k not in legacy_workflow_keys}
            tmp = SETTINGS_FILE.with_suffix(SETTINGS_FILE.suffix + ".cleanup.tmp")
            tmp.write_text(json.dumps(cleaned_saved, ensure_ascii=False, indent=2), encoding="utf-8")
            tmp.replace(SETTINGS_FILE)
        except Exception:
            pass
    # The old DEFAULTS object intentionally remains available to runtime
    # compatibility code, but the persistent store is now whitelist-only.
    return data


