_SESSION_LOCK=threading.RLock(); _SESSION_LAST_SEEN={}; _SESSION_TTL=2*3600; _SESSION_CACHE={}; _SESSION_STORE=SessionStore(_PROJECT_STORE,_SESSION_TTL); _SESSION_CLEANER_STOP=threading.Event()
def _session_state(sid=None):
    sid=str(sid or _SESSION_ID.get() or '__internal__')
    with _SESSION_LOCK:
        if sid not in _SESSION_CACHE:_SESSION_CACHE[sid]=_SESSION_STORE.load(sid)
        _SESSION_LAST_SEEN[sid]=time.monotonic(); return _SESSION_CACHE[sid]
