class _SessionFlag:
    def __init__(self,name,default=False):self.name=name;self.default=bool(default)
    def _state(self):return _session_state()
    def set(self):self._state()[f'__flag__:{self.name}']=True;_session_commit()
    def clear(self):self._state()[f'__flag__:{self.name}']=False;_session_commit()
    def is_set(self):return bool(self._state().get(f'__flag__:{self.name}',self.default))
    def wait(self,timeout=None):
        deadline=None if timeout is None else time.monotonic()+float(timeout)
        while not self.is_set():
            if deadline is not None and time.monotonic()>=deadline:return False
            time.sleep(.05)
        return True
class _SessionScalar:
    def __init__(self,name,default=None):self.name=name;self.default=default
    def _state(self):return _session_state()
    def get(self):return self._state().get(f'__scalar__:{self.name}',self.default)
    def set(self,value):self._state()[f'__scalar__:{self.name}']=value;_session_commit()
    def __bool__(self):return bool(self.get())
    def __float__(self):return float(self.get() or 0.0)
    def __str__(self):return str(self.get() or '')
