def _cleanup_runtime_sessions():
    while not _SESSION_CLEANER_STOP.wait(300):
        try:_SESSION_STORE.gc()
        except Exception:pass
        cutoff=time.monotonic()-_SESSION_TTL
        for sid in [x for x,t in list(_SESSION_LAST_SEEN.items()) if t<cutoff and x!='__internal__']:_session_pop(sid)
