def _activate_gradio_session(request=None):
    sid=str(getattr(request,'session_hash',None) or '__internal__');_SESSION_ID.set(sid);_session_state(sid);return sid
def _wrap_gradio_callback(fn):
    if fn is None or getattr(fn,'_vhung_runtime_wrapped',False):return fn
    if inspect.isasyncgenfunction(fn):
        async def async_gen(*args,request:gr.Request=None,**kwargs):
            _activate_gradio_session(request)
            async for item in fn(*args,**kwargs):
                yield item
        wrapped=async_gen
    elif inspect.iscoroutinefunction(fn):
        async def async_fn(*args,request:gr.Request=None,**kwargs):_activate_gradio_session(request);return await fn(*args,**kwargs)
        wrapped=async_fn
    elif inspect.isgeneratorfunction(fn):
        async def async_generator_bridge(*args,request:gr.Request=None,**kwargs):
            _activate_gradio_session(request)
            async for item in stream_sync_generator(fn,*args,**kwargs):yield item
        wrapped=async_generator_bridge
    else:
        async def async_bridge(*args,request:gr.Request=None,**kwargs):
            _activate_gradio_session(request);return await asyncio.get_running_loop().run_in_executor(_ASYNC_EXECUTOR,lambda:contextvars.copy_context().run(fn,*args,**kwargs))
        wrapped=async_bridge
    wrapped.__name__=getattr(fn,'__name__','vhung_callback');wrapped.__qualname__=getattr(fn,'__qualname__',wrapped.__name__);wrapped.__doc__=getattr(fn,'__doc__',None);wrapped._vhung_runtime_wrapped=True;return wrapped

