def save_settings() -> None:
    """Atomically persist settings and Gemini credentials under one process lock."""
    with _SETTINGS_WRITE_LOCK:
        SETTINGS["gemini_model"] = GEMINI_MODEL
        key = str(SETTINGS.get("gemini_api_key") or "").strip()
        previous_key = str(getattr(save_settings, "_last_saved_key", "") or "").strip()
        if key:
            save_settings._last_saved_key = key
        elif previous_key:
            save_settings._last_saved_key = previous_key
        SETTINGS["gemini_api_key"] = key
        SETTINGS_FILE.parent.mkdir(parents=True, exist_ok=True)
        tmp = SETTINGS_FILE.with_suffix(SETTINGS_FILE.suffix + ".tmp")
        tmp.write_text(json.dumps(SETTINGS.persisted_snapshot(), ensure_ascii=False, indent=2), encoding="utf-8")
        tmp.replace(SETTINGS_FILE)
        key_store = BASE / "gemini_keys.json"
        if key:
            try:
                key_tmp = GEMINI_KEY_FILE.with_suffix(GEMINI_KEY_FILE.suffix + ".tmp")
                key_tmp.write_text(key, encoding="utf-8")
                key_tmp.replace(GEMINI_KEY_FILE)
            except Exception as exc:
                workflow_cmd_log("SETTINGS", "GEMINI_KEY_FILE_WRITE_FAIL", level="WARN", error=str(exc)[:500])
            try:
                existing=[]
                if key_store.exists():
                    raw=json.loads(key_store.read_text(encoding="utf-8"))
                    existing=raw.get("keys",[]) if isinstance(raw,dict) else []
                    if not isinstance(existing,list): existing=[]
                merged=[]
                for candidate in [key,*existing]:
                    candidate=str(candidate or "").strip()
                    if candidate and candidate not in merged: merged.append(candidate)
                tmp_store=key_store.with_suffix(key_store.suffix+".tmp")
                tmp_store.write_text(json.dumps({"keys":merged[:10]},ensure_ascii=False,indent=2)+"\n",encoding="utf-8")
                tmp_store.replace(key_store)
            except Exception as exc:
                workflow_cmd_log("SETTINGS", "GEMINI_KEY_STORE_WRITE_FAIL", level="WARN", error=str(exc)[:700])
        else:
            # Empty is an explicit delete. Do not leave a stale credential that
            # load_settings() can resurrect on the next process start.
            try:
                GEMINI_KEY_FILE.unlink(missing_ok=True)
            except Exception as exc:
                workflow_cmd_log("SETTINGS", "GEMINI_KEY_FILE_DELETE_FAIL", level="WARN", error=str(exc)[:500])
            try:
                if key_store.exists():
                    raw=json.loads(key_store.read_text(encoding="utf-8"))
                    existing=raw.get("keys",[]) if isinstance(raw,dict) else []
                    if not isinstance(existing,list): existing=[]
                    # Remove the key currently held in memory if there is one;
                    # an explicit empty UI field means delete that credential, not
                    # destructive deletion of unrelated keys in a multi-key store.
                    active_to_remove=str(getattr(save_settings, "_last_saved_key", "") or "").strip()
                    if active_to_remove:
                        existing=[str(x).strip() for x in existing if str(x).strip() != active_to_remove]
                    tmp_store=key_store.with_suffix(key_store.suffix+".tmp")
                    tmp_store.write_text(json.dumps({"keys":existing[:10]},ensure_ascii=False,indent=2)+"\n",encoding="utf-8")
                    tmp_store.replace(key_store)
            except Exception as exc:
                workflow_cmd_log("SETTINGS", "GEMINI_KEY_STORE_DELETE_FAIL", level="WARN", error=str(exc)[:700])


