def normalize_gemini_visual_directive_mode(value) -> str:
    """Normalize a Gemini directive from either its stored mode OR its human text.

    V33 fixes the UI bug where workflow_config.json could contain the correct
    Character Lock command while the dropdown still rendered ``auto``.
    """
    raw = str(value or "").strip().lower()
    if raw in {"none", "character", "subject", "all", "auto"}:
        return raw
    # Accept the labels/commands that older config writers stored instead of the
    # short mode token. This makes the persisted config self-describing.
    if "character lock" in raw or "giữ nhân vật" in raw or "identity + ngoại hình" in raw:
        return "character"
    if "subject lock" in raw or "giữ chủ thể" in raw or "anatomy / sản phẩm" in raw:
        return "subject"
    if "world lock" in raw or "giữ thế giới" in raw or "character identity, subject identity" in raw:
        return "all"
    if "scene independent" in raw or "scene độc lập" in raw or "không ép giữ identity" in raw:
        return "none"
    if "gemini auto directive" in raw or "gemini tự quyết" in raw or "tự sinh chỉ thị" in raw:
        return "auto"
    return "auto"

def _workflow_config_raw() -> dict:
    """Read workflow_config.json directly; settings.json is never the owner."""
    try:
        raw = read_json(WORKFLOW_CONFIG_FILE, {})
        return raw if isinstance(raw, dict) else {}
    except Exception:
        return {}

def workflow_profile_directive_mode(name=None) -> str:
    """Return the directive mode stored by the selected workflow profile.

    This deliberately bypasses SETTINGS so a stale ``auto`` runtime value can
    never overwrite the value visibly stored in workflow_config.json.
    """
    raw = _workflow_config_raw()
    profiles = raw.get("profiles") if isinstance(raw.get("profiles"), dict) else raw
    if not isinstance(profiles, dict):
        profiles = {}
    requested = str(name or "").strip()
    active = str(raw.get("active_profile") or "").strip()
    selected = requested or active or str(SETTINGS.get("workflow_profile", "") or "").strip()
    cfg = profiles.get(selected) if selected else None
    if isinstance(cfg, dict):
        # Prefer the explicit mode, then infer it from the stored command text.
        if cfg.get("gemini_visual_directive_mode") not in (None, ""):
            return normalize_gemini_visual_directive_mode(cfg.get("gemini_visual_directive_mode"))
        if cfg.get("gemini_visual_directive"):
            return normalize_gemini_visual_directive_mode(cfg.get("gemini_visual_directive"))
    return normalize_gemini_visual_directive_mode(SETTINGS.get("gemini_visual_directive_mode", "auto"))

