def normalize_voice_value(value: str) -> str:
    """Canonicalize every Voice reference to a direct file path.

    New storage is flat: <app>/voice/<VoiceName>.wav.  Older workflow configs
    may still contain values such as ``profile:Wellness_Fix``; when the matching
    flat WAV exists, transparently migrate that reference to the real file.
    """
    raw = str(value or "").strip()
    if not raw:
        return ""

    # Legacy profile reference -> flat voice library file.
    if raw.lower().startswith("profile:"):
        name = raw.split(":", 1)[1].strip()
        if name:
            direct = VOICE_LIBRARY / f"{safe_name(Path(name).stem)}.wav"
            if direct.is_file():
                return str(direct)
            # Compatibility with an existing flat voice using another supported
            # audio extension. New Voice creation still always writes WAV.
            stem = safe_name(Path(name).stem)
            for ext in SUPPORTED_AUDIO:
                candidate = VOICE_LIBRARY / f"{stem}{ext}"
                if candidate.is_file():
                    return str(candidate)
        return raw

    path = Path(raw).expanduser()
    if path.is_file():
        return str(path)

    # Historical configs sometimes stored only ``Wellness_Fix`` or
    # ``Wellness_Fix.wav`` instead of the absolute path.
    candidate = VOICE_LIBRARY / (safe_name(path.stem) + ".wav")
    if candidate.is_file():
        return str(candidate)
    return raw


