def _project_image_dir(root: Path) -> Path:
    return _project_media_dir(root) / "Hình ảnh"

def _project_audio_dir(root: Path) -> Path:
    return _project_media_dir(root) / "Âm thanh"







def _merge_project_tree(src: Path, dst: Path) -> None:
    """Merge legacy project data into the canonical 3-folder layout."""
    if not src.exists():
        return
    dst.mkdir(parents=True, exist_ok=True)
    if src.is_file():
        if not dst.exists():
            shutil.move(str(src), str(dst))
        return
    for item in list(src.iterdir()):
        target = dst / item.name
        if item.is_dir():
            _merge_project_tree(item, target)
            try:
                if item.exists() and not any(item.iterdir()): item.rmdir()
            except Exception: pass
        else:
            if not target.exists():
                try: shutil.move(str(item), str(target))
                except Exception:
                    shutil.copy2(item, target)
                    try: item.unlink()
                    except Exception: pass


def _migrate_legacy_project_layout(root: Path) -> None:
    """Migrate the old many-folder Project layout once, without overwriting files."""
    content, media, export = _project_content_dir(root), _project_media_dir(root), _project_export_dir(root)
    for d in (content, media, export): d.mkdir(parents=True, exist_ok=True)
    mappings = {
        "Kịch bản": content / "Kịch bản",
        "Cảnh": content / "Cảnh",
        "Prompt": content / "Prompt",
        "Hình ảnh": media / "Hình ảnh",
        "Âm thanh": media / "Âm thanh",
        "Phụ đề": export / "Phụ đề",
        "Dòng thời gian": export / "Dòng thời gian",
        "QC": export / "QC",
        "CapCut": export / "CapCut",
        "Engine": export / "QC" / "Legacy_Engine",
        "FluxJS": export / "QC" / "Legacy_Engine",
        "Debug": export / "QC" / "Debug",
    }
    for old_name, new_path in mappings.items():
        old = root / old_name
        if old.exists():
            _merge_project_tree(old, new_path)
            try:
                if old.is_dir() and not any(old.iterdir()): old.rmdir()
            except Exception: pass

    # Canonical master: ONE file only. Remove the legacy duplicate after migration.
    master = media / "Âm thanh" / "Voice Full" / "Voice_Full.wav"
    legacy = media / "Âm thanh" / "voice.wav"
    if legacy.exists():
        if not master.exists():
            master.parent.mkdir(parents=True, exist_ok=True)
            try: shutil.move(str(legacy), str(master))
            except Exception:
                shutil.copy2(legacy, master); legacy.unlink(missing_ok=True)
        else:
            try: legacy.unlink()
            except Exception: pass

def list_projects():
    """Discover project names without creating anything.

    Once a Project is connected, expose ONLY that connected project to workflow
    selectors. This stops the app from treating Downloads or another parent
    folder as a project. Before connection, return existing child folders only.
    """
    bound = str(SETTINGS.get("selected_project_path", "") or "").strip()
    if PROJECT_CONNECTED and bound:
        bp = Path(bound).expanduser()
        return [bp.name] if bp.exists() and bp.is_dir() else [safe_name(bp.name)]
    if bound:
        bp = Path(bound).expanduser()
        return [bp.name] if bp.exists() and bp.is_dir() else []
    chosen = (SETTINGS.get("project_output_dir", "") or "").strip()
    if not chosen:
        return []
    base = Path(chosen).expanduser()
    if not base.exists() or not base.is_dir():
        return []
    return sorted([p.name for p in base.iterdir() if p.is_dir()], key=str.lower)

def list_voice_files():
    """Return the flat voice library: one audio file per voice, no profile folders."""
    root = VOICE_LIBRARY
    if not root.is_dir():
        return []
    found = {}
    try:
        for p in root.iterdir():
            if p.is_file() and p.suffix.lower() in SUPPORTED_AUDIO:
                found[str(p.resolve()).lower()] = str(p)
    except OSError:
        return []
    return sorted(found.values(), key=lambda x: Path(x).name.lower())


