def find_python311():
    candidates = []
    launcher = shutil.which("py")
    if launcher:
        candidates.append([launcher, "-3.11"])
    python = shutil.which("python")
    if python:
        candidates.append([python])
    for cmd in candidates:
        try:
            r = subprocess.run(cmd + ["-c", "import sys; print(f'{sys.version_info[0]}.{sys.version_info[1]}')"], capture_output=True, text=True, timeout=10)
            if r.returncode == 0 and r.stdout.strip() == "3.11":
                return cmd
        except Exception:
            pass
    return candidates[0] if candidates else None


def venv_python(path: Path) -> Path:
    return path / "Scripts" / "python.exe"


def _register_managed_process(proc):
    if proc:
        try: _MANAGED_CHILD_PIDS.add(int(proc.pid))
        except Exception: pass

def _kill_managed_process_tree(pid):
    try: pid=int(pid)
    except Exception: return
    if psutil is not None:
        try:
            p=psutil.Process(pid); children=list(reversed(p.children(recursive=True)))
            for child in children:
                try: child.terminate()
                except Exception: pass
            try: psutil.wait_procs(children,timeout=3)
            except Exception: pass
            for child in children:
                try:
                    if child.is_running(): child.kill()
                except Exception: pass
            try: p.terminate(); p.wait(timeout=3)
            except Exception:
                try: p.kill()
                except Exception: pass
            return
        except Exception: pass
    try: os.kill(pid,15)
    except Exception: pass

def cleanup_managed_ai_processes():
    """Normal-exit cleanup + orphan reaping. User applications are intentionally excluded."""
    pids = set(_MANAGED_CHILD_PIDS)
    try:
        for pf in SERVERS.glob("*.pid"):
            try:
                pids.add(int(pf.read_text(encoding="utf-8").strip()))
            except Exception:
                pass
    except Exception:
        pass
    for pid in pids:
        _kill_managed_process_tree(pid)
    _MANAGED_CHILD_PIDS.clear()


def reap_stale_ai_processes():
    """At startup, remove AI processes left behind by a previous hard crash."""
    if psutil is None and os.name != "nt":
        return
    for pf in SERVERS.glob("*.pid"):
        try:
            pid = int(pf.read_text(encoding="utf-8").strip())
        except Exception:
            continue
        alive = False
        try:
            if psutil is not None:
                alive = psutil.pid_exists(pid)
            else:
                out = subprocess.run(["tasklist", "/FI", f"PID eq {pid}", "/NH"],
                                     capture_output=True, text=True, timeout=4)
                alive = any(
                    len(parts) >= 2 and parts[1].strip() == str(pid)
                    for parts in (line.split() for line in out.stdout.splitlines())
                )
        except Exception:
            pass
        if alive:
            # Only reap a PID if its health endpoint is not alive. A healthy server
            # may have been intentionally left running across a UI restart.
            name = pf.stem
            healthy = False
            try:
                if name in ENGINE_INFO:
                    healthy = requests.get(ENGINE_INFO[name]["url"] + "/health", timeout=1.5).ok
            except Exception:
                healthy = False
            if not healthy:
                _kill_managed_process_tree(pid)
                try:
                    pf.unlink()
                except Exception:
                    pass


atexit.register(cleanup_managed_ai_processes)

class ServerManager:
    def __init__(self):
        reap_stale_ai_processes()
        self.state = read_json(ENGINE_STATE_FILE, {}) or {}

    def _save(self):
        write_json(ENGINE_STATE_FILE, self.state)

    def pid_file(self, name):
        return SERVERS / f"{name}.pid"

    def log_file(self, name):
        return SERVERS / f"{name}.log"

    def get_pid(self, name):
        try:
            return int(self.pid_file(name).read_text(encoding="utf-8"))
        except Exception:
            return None

    def running(self,name):
        pid=self.get_pid(name)
        if not pid: return False
        if psutil is not None:
            try: return bool(psutil.pid_exists(pid))
            except Exception: return False
        try: os.kill(pid,0); return True
        except Exception: return False

    def installed(self, name):
        return venv_python(ENGINE_INFO[name]["venv"]).exists()

    def health(self, name):
        try:
            r = requests.get(ENGINE_INFO[name]["url"] + "/health", timeout=2.5)
            return r.ok and bool(r.json().get("ok"))
        except Exception:
            return False

    def model_ready(self, name):
        """Check model readiness without recursively scanning huge HF caches."""
        if name == "cloneprep":
            return self.installed(name)
        state = self.state.get(name, {})
        if bool(state.get("model_ready", False)):
            return True

        roots = [MODEL_ROOT / name, MODEL_ROOT / name / "hub", MODEL_ROOT / "hub"]
        hf_home = os.environ.get("HF_HOME")
        if hf_home:
            roots.append(Path(hf_home) / "hub")
        roots.append(Path.home() / ".cache" / "huggingface" / "hub")

        expected = {
            "chatterbox": {"t3_mtl23ls_v3.safetensors", "t3_23lang.safetensors", "t3_cfg.safetensors", "s3gen_v3.safetensors", "s3gen.safetensors", "tokenizer.json", "mtl_tokenizer.json"},
            "vieneu": {"model.safetensors", "speaker_encoder.onnx"},
            "omnivoice": set(),
        }.get(name, set())

        def shallow_files(root: Path, max_depth=4):
            root = Path(root)
            if not root.is_dir():
                return set(), []
            found_names, found_paths = set(), []
            stack = [(root, 0)]
            while stack:
                current, depth = stack.pop()
                try:
                    with os.scandir(current) as it:
                        for entry in it:
                            try:
                                if entry.is_file(follow_symlinks=False):
                                    low = entry.name.lower()
                                    found_names.add(low)
                                    found_paths.append(str(Path(entry.path)).lower())
                                elif entry.is_dir(follow_symlinks=False) and depth < max_depth:
                                    stack.append((Path(entry.path), depth + 1))
                            except OSError:
                                continue
                except OSError:
                    continue
            return found_names, found_paths

        names, paths = set(), []
        # Local engine directories are small and can be checked normally. HF
        # caches are bounded to a few directory levels (snapshots/model files)
        # rather than traversing every blob in a multi-GB cache.
        for root in roots:
            n, ps = shallow_files(root, max_depth=2 if ".cache" not in str(root).lower() else 4)
            names.update(n); paths.extend(ps)
            if name == "chatterbox" and {"tokenizer.json", "mtl_tokenizer.json"} & names and any(x in names for x in ("t3_mtl23ls_v3.safetensors", "t3_23lang.safetensors", "t3_cfg.safetensors")) and any(x in names for x in ("s3gen_v3.safetensors", "s3gen.safetensors")):
                return True
            if name == "vieneu" and "model.safetensors" in names and ("speaker_encoder.onnx" in names or any("vieneu" in p for p in paths)):
                return True
            if name == "omnivoice" and any(x.endswith((".safetensors", ".gguf", ".pt", ".pth")) for x in paths) and any("omnivoice" in p for p in paths):
                return True
        return bool(paths) if name not in ("chatterbox", "vieneu", "omnivoice") else False

    def stop(self, name):
        pid=self.get_pid(name)
        if pid: _kill_managed_process_tree(pid)
        try: self.pid_file(name).unlink(missing_ok=True)
        except Exception as exc: workflow_cmd_log("SERVER","PID_FILE_REMOVE_FAIL",level="WARN",engine=name,error=str(exc)[:500])
        gc.collect()
        return f"✓ {ENGINE_INFO[name]['short']} đã tắt."

    def stop_all(self, keep=None):
        msgs = []
        for name in ENGINE_INFO:
            if name != keep and self.running(name):
                msgs.append(self.stop(name))
        return msgs

    def start(self, name):
        if not self.installed(name):
            return f"✕ {ENGINE_INFO[name]['short']}: chưa cài environment. Bấm 'Cài / Sửa Environment'."
        self.stop_all(keep=name)
        if self.running(name):
            return f"✓ {ENGINE_INFO[name]['short']} đã chạy."
        info = ENGINE_INFO[name]
        log = self.log_file(name)
        with log.open("a", encoding="utf-8") as fh:
            fh.write(f"\n[{datetime.now().isoformat()}] START {name}\n")
        try:
            flags = subprocess.CREATE_NEW_PROCESS_GROUP | getattr(subprocess, "CREATE_NO_WINDOW", 0)
            env = os.environ.copy()
            # Do not create a model cache merely by starting a voice server.
            # The server may use its existing user/HF cache; explicit model update
            # owns the tool model directory.
            env.pop("HF_HOME", None)
            env["HF_HUB_DISABLE_TELEMETRY"] = "1"
            # VieNeu v3 Turbo uses CUDA graphs on GPU by default. On this
            # Windows/RTX 3060 stack a failed capture can poison the CUDA RNG
            # state and surface as:
            # "Offset increment outside graph capture encountered unexpectedly".
            # Force the documented plain-frame path for reliability.
            if name == "vieneu":
                env["VIENEU_FUSED_FRAME"] = "0"
            proc = subprocess.Popen(
                [str(venv_python(info["venv"])), str(info["script"]), "--port", str(info["port"])],
                stdout=log.open("a", encoding="utf-8"),
                stderr=subprocess.STDOUT,
                creationflags=flags,
                env=env,
            )
            _register_managed_process(proc)
            self.pid_file(name).write_text(str(proc.pid), encoding="utf-8")
        except Exception as exc:
            return f"✕ Không mở được server: {exc}"
        for _ in range(50):
            if self.health(name):
                self.state.setdefault(name, {})["last_started"] = datetime.now().isoformat()
                self._save()
                return f"✓ {info['short']} đang chạy — {info['url']}"
            time.sleep(0.4)
        return f"⚠ Process đã mở nhưng health chưa sẵn sàng. Xem log: {log}"

    def install_cmd(self,name,repair=False):
        info=ENGINE_INFO[name]; creator=find_python311()
        if not creator: return '✕ Không tìm thấy Python 3.11.'
        action='REPAIR' if repair else 'INSTALL'; py=venv_python(info['venv'])
        def _run():
            try:
                info['venv'].mkdir(parents=True,exist_ok=True)
                if not py.exists():
                    ok,tail,err=_raiw_stream_command(creator+['-m','venv',str(info['venv'])],status_cb=lambda m:_master_cmd(str(m),'ENV'),timeout=1800,label=f'{name.upper()}_VENV')
                    if not ok: raise RuntimeError(err or tail or 'venv creation failed')
                for spec in info['install']:
                    argv=[str(py)]+__import__('shlex').split(spec)
                    ok,tail,err=_raiw_stream_command(argv,status_cb=lambda m:_master_cmd(str(m),'ENV'),timeout=7200,label=f'{name.upper()}_{action}')
                    if not ok: raise RuntimeError(err or tail or 'install failed')
                _master_cmd(f'✓ {name.upper()} ENV {action} DONE','ENV')
            except Exception as exc: _master_cmd(f'✕ {name.upper()} ENV {action}: {exc}','ERROR')
        threading.Thread(target=_run,name=f'VHUNG-{name}-env-install',daemon=True).start()
        return f'⏳ Đã bắt đầu {action.lower()} {info["short"]} bằng subprocess native.'

    def update_model(self, name):
        if name == "cloneprep":
            return "✓ Clone Prep không có TTS model. Dùng Cập nhật Environment để cập nhật faster-whisper."
        if not self.installed(name):
            return f"✕ {ENGINE_INFO[name]['short']} chưa có environment."
        self.stop_all()
        py = venv_python(ENGINE_INFO[name]["venv"])
        repo = ENGINE_INFO[name]["hf_model"]
        target = MODEL_ROOT / name
        target.mkdir(parents=True, exist_ok=True)
        code = (
            "from huggingface_hub import snapshot_download; "
            "import sys; "
            "path=snapshot_download(repo_id=sys.argv[1], local_dir=sys.argv[2]); "
            "print(path)"
        )
        env = os.environ.copy()
        env["HF_HOME"] = str(target)
        env["HF_HUB_DISABLE_TELEMETRY"] = "1"
        try:
            r = subprocess.run([str(py), "-c", code, repo, str(target)], capture_output=True, text=True, timeout=7200, env=env)
            if r.returncode != 0:
                detail = (r.stderr or r.stdout or "Unknown error")[-4000:]
                return "✕ Tải model thất bại:\n" + detail
            if not self._model_files_present(name):
                return f"✕ Đã tải từ {repo} nhưng chưa nhận dạng được bộ model {ENGINE_INFO[name]['short']}. Kiểm tra thư mục: {target}"
            self.state.setdefault(name, {})["model_ready"] = True
            self.state[name]["model_path"] = str(target)
            self.state[name]["model_updated"] = datetime.now().isoformat()
            self._save()
            if name == "chatterbox":
                return "✓ Chatterbox Multilingual V3 đã tải/cập nhật thành công.\n✓ Bộ model đã được nhận dạng."
            return f"✓ Model {ENGINE_INFO[name]['short']} đã cập nhật và nhận dạng thành công."
        except Exception as exc:
            return f"✕ Model update error: {exc}"

    def _model_files_present(self, name):
        old = self.state.get(name, {})
        if old.get("model_ready"):
            return True
        return self.model_ready(name)

    def info(self, name):
        i = ENGINE_INFO[name]
        env_ok = self.installed(name)
        model_ok = self.model_ready(name)
        running = self.running(name)
        health = self.health(name) if running else False
        return "\n".join([
            i["title"],
            f"Ngôn ngữ: {i['languages']}",
            f"Môi trường: {'✅ Nhận dạng thành công' if env_ok else '❌ Chưa có'}",
            f"Model: {'✅ Sẵn sàng' if model_ok else '⚠ Chưa có'}",
            f"Server: {'✅ Đang chạy' if running and health else '⏹ Đã tắt'}",
            "",
            i["best"],
        ])

    def table(self):
        rows = []
        for name, i in ENGINE_INFO.items():
            env_ok = self.installed(name)
            model_ok = self.model_ready(name)
            running = self.running(name)
            healthy = self.health(name) if running else False
            rows.append([
                i["short"],
                i["languages"],
                "✅ Nhận dạng thành công" if env_ok else "❌ Chưa có",
                "✅ Sẵn sàng" if model_ok else "⚠ Thiếu model",
                "✅ Đang chạy" if healthy else "⏹ Đã tắt",
            ])
        return rows

MANAGER = ServerManager()


# Lightweight local language detection for the script box.  It avoids sending
# the narration to an external service just to choose the TTS engine.
def detect_script_language(text: str) -> str:
    text = (text or "").strip()
    if not text:
        return "vi"
        # Script-family detection first: these are much more reliable than word lists.
    ranges = {
        "zh": lambda c: "\u4e00" <= c <= "\u9fff",
        "ja": lambda c: ("\u3040" <= c <= "\u30ff") or ("\u31f0" <= c <= "\u31ff"),
        "ko": lambda c: "\uac00" <= c <= "\ud7af",
        "ru": lambda c: "\u0400" <= c <= "\u04ff",
        "el": lambda c: "\u0370" <= c <= "\u03ff",
        "ar": lambda c: "\u0600" <= c <= "\u06ff",
        "he": lambda c: "\u0590" <= c <= "\u05ff",
        "hi": lambda c: "\u0900" <= c <= "\u097f",
    }
    counts = {k: sum(1 for c in text if fn(c)) for k, fn in ranges.items()}
    strongest = max(counts, key=counts.get)
    if counts[strongest] >= 3:
        return strongest

    low = " " + re.sub(r"[^a-zA-ZÀ-ỹĐđ'\s]", " ", text.lower()) + " "
    # Vietnamese has distinctive diacritics; use them before generic Latin lists.
    vi_marks = sum(1 for c in text.lower() if c in "ăâđêôơưáàảãạấầẩẫậắằẳẵặéèẻẽẹếềểễệíìỉĩịóòỏõọốồổỗộớờởỡợúùủũụứừửữựýỳỷỹỵ")
    if vi_marks >= 2 or re.search(r"\b(và|của|trong|một|những|được|với|cho|là|có|không|này|người|các|từ|khi|đã|sẽ)\b", low):
        return "vi"

    # LANGUAGE_CATALOG intentionally has no Thai entry; do not return a phantom
    # "th" locale here. Unsupported Latin/script families fall through to English.
    # Latin-language fallback: score common function words.  English is the
    # important default for production scripts and is selected when it wins.
    lexicons = {
        "en": "the and of to in is that for with this from are was were be as on it by an a i you he she they we has have had will can not do does at or but about into than then their them these those when where who what which how with".split(),
        "es": "el la los las de del que y en un una es por para con como este esta estos estas los se no".split(),
        "fr": "le la les de des du et en un une est pour avec dans que qui ce cette ces pas sur".split(),
        "de": "der die das den dem des und ist ein eine mit von zu für auf nicht im in den".split(),
        "pt": "o a os as de do da e em um uma que para com por não no na".split(),
        "it": "il lo la gli le di del della e che un una per con non nel nella".split(),
        "nl": "de het een en van in is voor met dat die niet op aan".split(),
        "tr": "bir ve bu için ile olan da de mi değil çok olarak".split(),
        "pl": "i w z na że nie jest do dla się jak to od".split(),
    }
    words = re.findall(r"[a-zA-ZÀ-ÿ']+", low)
    scores = {lang: sum(words.count(w) for w in vocab) for lang, vocab in lexicons.items()}
    best = max(scores, key=scores.get)
    if scores[best] >= 2:
        return best
    return "en"


def detect_script_and_engine(script: str, requested_engine: str = "auto"):
    detected = detect_script_language(script)
    selected = route_engine(detected) if requested_engine in (None, "", "auto") else requested_engine
    return detected, selected


def route_engine(language: str) -> str:
    if language == "vi":
        return "vieneu"
    if language in CHATTERBOX_LANGS:
        return "chatterbox"
    return "omnivoice"


def engine_choices(language: str):
    rec = route_engine(language)
    return [
        (f"TỰ ĐỘNG → {ENGINE_INFO[rec]['short']}", "auto"),
        ("VIP 1 - Chatterbox", "chatterbox"),
        ("VIP 2 - OmniVoice", "omnivoice"),
        ("VIP 3 - VieNeu", "vieneu"),
    ]


def resolve_engine(language: str, engine: str) -> str:
    return route_engine(language) if engine == "auto" else engine


def local_voice_choices():
    return audio_files_for_ui()


def profile_choices():
    # Legacy function name retained for compatibility; returns flat WAV voices.
    return audio_files_for_ui()


def filter_voice_choices(query: str = ""):
    q = str(query or "").strip().casefold()
    choices = audio_files_for_ui()
    return choices if not q else [(label, value) for label, value in choices if q in label.casefold()]


def server_default_voice_choices(language: str, engine: str):
    e = resolve_engine(language, engine)
    out = []
    if e == "chatterbox":
        out.append(("Chatterbox — Voice mặc định", "default"))
    elif e == "vieneu":
        out.append(("VieNeu — Voice dựng sẵn", "default"))
    elif e == "omnivoice":
        out.append(("OmniVoice — Auto Voice", "default"))
    return out


def _effective_voice_language(language: str, script: str = "") -> str:
    """Resolve UI language without defaulting Auto to English.

    Vietnamese projects must stay on VieNeu when Language=Auto; older builds
    used English as the UI fallback and therefore showed/selected Chatterbox.
    """
    lang = str(language or "auto").strip().lower()
    if lang in LANGUAGE_CATALOG and lang != "auto":
        return lang
    detected = detect_script_language(script or SETTINGS.get("workflow_script", "") or "")
    if detected in LANGUAGE_CATALOG and detected != "auto":
        return detected
    saved = str(SETTINGS.get("selected_language", "auto") or "auto").strip().lower()
    if saved in LANGUAGE_CATALOG and saved != "auto":
        return saved
    return "vi"


def _canonical_voice_for_engine(language: str, engine: str, voice: str = "", script: str = ""):
    """Return one consistent (language, requested-engine, resolved-engine, voice).

    The saved workflow profile is authoritative. Only the engine-specific
    *default* voice is normalized; a real reference audio/profile is preserved.
    """
    actual_lang = _effective_voice_language(language, script)
    requested = str(engine or "auto").strip().lower() or "auto"
    if requested not in ENGINE_INFO and requested != "auto":
        requested = "auto"
    resolved = resolve_engine(actual_lang, requested)
    choices = all_voice_choices(actual_lang, requested) if 'all_voice_choices' in globals() else []
    valid = {v for _, v in choices}
    selected = normalize_voice_value(voice or "")
    # A saved/user-selected Voice is authoritative.  Do NOT silently replace it
    # with VieNeu/engine `default` merely because the current voice index has not
    # discovered that entry yet.  The exact selected value is carried through the
    # workflow; UI code may inject a missing value into the visible choices.
    return actual_lang, requested, resolved, selected


def all_voice_choices(language: str, engine: str):
    # The workflow profile voice is authoritative. Keep a valid configured audio
    # path visible even if the library index did not discover it yet.
    choices = server_default_voice_choices(language, engine) + local_voice_choices()
    selected = normalize_voice_value(SETTINGS.get("selected_voice", "") or "")
    if selected and Path(selected).expanduser().is_file() and selected not in {v for _, v in choices}:
        choices.insert(0, (Path(selected).name, selected))
    return choices


def configured_voice_value(language: str, engine: str, requested=None):
    """Resolve the Voice for THIS RUN.

    IMPORTANT: `requested` is the live Voice dropdown value and is authoritative.
    `SETTINGS["selected_voice"]` is only a persisted workflow default/fallback.
    Creating or selecting a Voice for a run must never be silently replaced by an
    older persisted Voice (for example History.wav being replaced by Wellness_Fix.wav).
    """
    requested_value = normalize_voice_value(requested or "")
    if requested_value:
        return requested_value
    return normalize_voice_value(SETTINGS.get("selected_voice", "") or "")


def voice_choice_label(language: str, engine: str, value: str) -> str:
    choices = all_voice_choices(language, engine)
    return next((label for label, val in choices if val == value), Path(str(value)).name if value and Path(str(value)).expanduser().is_file() else (value or "(auto)"))


def voice_ref(choice: str):
    choice = normalize_voice_value(choice)
    if not choice:
        return None, None
    p = Path(str(choice)).expanduser()
    if p.is_file():
        return str(p), _VOICE_TRANSCRIPT_CACHE.get(str(p.resolve()).lower(), "")
    # Read old saved profile settings without recreating the old storage layout.
    if str(choice).startswith("profile:"):
        ref = profile_reference(str(choice).split(":", 1)[1])
        return ref, _VOICE_TRANSCRIPT_CACHE.get(str(Path(ref).resolve()).lower(), "") if ref else ""
    return None, None


def audio_preview_path(choice: str, profile: str | None = None):
    choice = normalize_voice_value(choice)
    if choice and Path(choice).exists():
        return choice
    if choice and choice.startswith("profile:"):
        ref = profile_reference(choice.split(":", 1)[1])
        return ref
    if profile:
        return profile_reference(profile)
    return None


def available_voice_preview(choice: str, profile: str):
    p = audio_preview_path(choice, profile)
    if not p:
        raise RuntimeError("Voice này không có file preview. Hãy dùng Nghe thử để tạo sample.")
    return p, "✓ Đang phát file voice đã chọn."
































# Gemini API key store — required before any Gemini stage is initialized.
# Keep this block module-level and above every caller (including startup checks).
GEMINI_KEYS_FILE = BASE / "gemini_keys.json"
_GEMINI_KEY_INDEX = 0
_GEMINI_KEY_LOCK = threading.RLock()

def _ensure_gemini_keys_file():
    """Create the Gemini key store without overwriting an existing key file."""
    GEMINI_KEYS_FILE.parent.mkdir(parents=True, exist_ok=True)
    if not GEMINI_KEYS_FILE.exists():
        GEMINI_KEYS_FILE.write_text(
            json.dumps({"keys": []}, ensure_ascii=False, indent=2) + "\n",
            encoding="utf-8",
        )


def _load_gemini_keys() -> list[str]:
    _ensure_gemini_keys_file()
    try:
        data = json.loads(GEMINI_KEYS_FILE.read_text(encoding="utf-8"))
    except Exception as exc:
        raise RuntimeError(f"Không đọc được gemini_keys.json: {exc}") from exc
    raw = data.get("keys", []) if isinstance(data, dict) else []
    if not isinstance(raw, list):
        raise RuntimeError('gemini_keys.json phải có dạng {"keys":["KEY_01", ...]}.')
    keys = []
    seen = set()
    for value in raw[:10]:
        key = str(value or "").strip()
        if key and key not in seen:
            keys.append(key)
            seen.add(key)
    return keys



_GEMINI_LAST_STRUCTURED_RESULT = {}
_GEMINI_STAGE_LOCK = threading.Lock()

class _GeminiExplicitResponseError(RuntimeError):
    def __init__(self, message, retryable=True, mode=""):
        super().__init__(message)
        self.retryable = bool(retryable)
        self.mode = str(mode or "")





def _gemini_key_error_is_rotatable(exc):
    text = str(exc or '').lower()
    return any(t in text for t in (
        '429', 'quota', 'rate limit', 'rate_limit', 'resource exhausted',
        'too many requests', '503', 'service unavailable', 'temporarily unavailable',
        '401', '403', 'unauthenticated', 'permission denied', 'api key'
    ))


def _gemini_transient_error(exc):
    text = str(exc or '').lower()
    return any(t in text for t in (
        'timeout', 'timed out', 'deadline', 'temporarily unavailable',
        'connection reset', 'connection aborted', '502', '504', '503',
        'internal server error', 'resource exhausted', 'overloaded'
    ))



def _gemini_topic_profile_schema() -> dict:
    """Strict B1 contract: classify the script and separate reusable topic rules from project data."""
    style_keys = [
        "visual_identity", "rendering_mode", "shape_language", "outline_style", "composition",
        "camera_framing", "lens_perspective", "lighting", "color_palette", "color_grading",
        "contrast_exposure", "environment_production_design", "texture_detail", "character_rendering",
        "facial_feature_style", "depth_of_field", "thumbnail_text_layout", "cinematic_language",
        "negative_style_rules", "style_lock",
    ]
    style_props = {k: {"type": "string"} for k in style_keys}
    return {
        "type": "object",
        "properties": {
            "topic": {"type": "string", "description": "Human-readable main topic, <= 12 words."},
            "topic_id": {"type": "string", "description": "Stable lowercase slug for the reusable topic library, e.g. history, health, science, technology."},
            "domain": {"type": "string", "description": "Broad domain inferred from the full script. Do not force a fixed enum; create a concise stable domain slug when needed."},
            "subtopic": {"type": "string", "description": "Specific reusable subtopic, e.g. prehistoric_humans or heart_health."},
            "narrative_angle": {"type": "string"},
            "visual_type": {"type": "string"},
            "text_in_image": {"type": "boolean"},
            "text_style": {"type": "string"},
            "style": {"type": "string", "description": "Project-only visual style lock for this video."},
            "style_bible": {
                "type": "object",
                "properties": style_props,
                "required": style_keys,
            },
            "character_bible": {
                "type": "object",
                "properties": {
                    "reference_received": {"type": "boolean"}, "identity": {"type": "string"},
                    "appearance": {"type": "string"}, "clothing": {"type": "string"},
                    "hair_face": {"type": "string"}, "body_language": {"type": "string"},
                    "continuity_rules": {"type": "string"}, "character_lock": {"type": "string"},
                },
                "required": ["reference_received", "identity", "appearance", "clothing", "hair_face", "body_language", "continuity_rules", "character_lock"],
            },
            "visual_rules": {
                "type": "object",
                "properties": {
                    "period_accuracy": {"type": "boolean"}, "architecture_accuracy": {"type": "boolean"},
                    "clothing_accuracy": {"type": "boolean"}, "weapon_accuracy": {"type": "boolean"},
                    "educational": {"type": "boolean"}, "non_graphic": {"type": "boolean"},
                    "anatomical_consistency": {"type": "boolean"},
                    "topic_specific_rules": {"type": "array", "items": {"type": "string"}},
                },
            },
            "continuity_rules": {
                "type": "object",
                "properties": {
                    "characters": {"type": "boolean"}, "locations": {"type": "boolean"},
                    "objects": {"type": "boolean"}, "timeline": {"type": "boolean"},
                    "subject": {"type": "boolean"}, "body_region": {"type": "boolean"},
                    "medical_concept": {"type": "boolean"},
                    "topic_specific_rules": {"type": "array", "items": {"type": "string"}},
                },
            },
            "competitor_style_confirmed": {"type": "boolean"},
            "competitor_evidence": {"type": "string"},
        },
        "required": [
            "topic", "topic_id", "domain", "subtopic", "narrative_angle", "visual_type",
            "text_in_image", "text_style", "style", "style_bible", "character_bible",
            "visual_rules", "continuity_rules", "competitor_style_confirmed", "competitor_evidence",
        ],
    }


def _gemini_b2_scene_schema() -> dict:
    """Strict JSON contract for Gemini B2 scene prompt generation.

    The defensive parser remains below as a compatibility guard, but normal B2
    requests now ask Gemini for this schema directly so scene IDs, media type,
    timestamps and continuity state are machine-readable at the API boundary.
    """
    state = {
        "type": "object",
        "properties": {
            "scene_id": {"type": "string"},
            "narration": {"type": "string"},
            "characters": {"type": "array", "items": {"type": "string"}},
            "location": {"type": "string"},
            "objects": {"type": "array", "items": {"type": "string"}},
            "action": {"type": "string"},
            "continuity_from_previous": {"type": "string"},
            "style_anchor": {"type": "string"},
            "state_after": {"type": "string"},
            "end_style_lock": {"type": "string"},
            "timestamp_start": {"type": "string"},
            "timestamp_end": {"type": "string"},
            "text_in_image": {"type": "boolean"},
            "text_content": {"type": "string"},
            "text_position": {"type": "string"},
        },
        "required": [
            "scene_id", "narration", "characters", "location", "objects",
            "action", "continuity_from_previous", "style_anchor",
            "state_after", "end_style_lock", "timestamp_start", "timestamp_end",
            "text_in_image", "text_content", "text_position",
        ],
    }
    return {
        "type": "object",
        "properties": {
            "scenes": {
                "type": "array",
                "items": {
                    "type": "object",
                    "properties": {
                        "scene_id": {"type": "string"},
                        "media_type": {"type": "string", "enum": ["image", "video"]},
                        "timestamp_start": {"type": "string"},
                        "timestamp_end": {"type": "string"},
                        "prompt": {"type": "string"},
                        "state": state,
                    },
                    "required": ["scene_id", "media_type", "timestamp_start", "timestamp_end", "prompt", "state"],
                },
            }
        },
        "required": ["scenes"],
    }


def _topic_structured_result_valid(obj: dict) -> bool:
    if not isinstance(obj, dict):
        return False
    required = ("topic", "topic_id", "domain", "subtopic", "style", "style_bible", "visual_rules", "continuity_rules")
    if any(not str(obj.get(k) or "").strip() for k in ("topic", "topic_id", "domain", "style")):
        return False
    if not isinstance(obj.get("style_bible"), dict) or not isinstance(obj.get("visual_rules"), dict) or not isinstance(obj.get("continuity_rules"), dict):
        return False
    return all(k in obj for k in required)


def _gemini_channel_search_tool_urls(channel_urls, project=""):
    """Resolve a public YouTube channel to recent public video URLs without spending a Gemini request.

    The user supplies only the channel URL. We resolve the channel ID from the public channel page
    (or directly from /channel/UC...) and read YouTube's public RSS feed. The returned watch URLs
    are then attached to the SAME B1 Gemini request as native YouTube video inputs. This avoids
    the previous extra Gemini discovery call, which could consume quota and produce 429 errors.
    """
    urls = []
    for u in (channel_urls or []):
        u = str(u or "").strip()
        if u and u not in urls:
            urls.append(u)
    if not urls:
        return []
    out = []
    try:
        import xml.etree.ElementTree as ET
        yt_ns = "http://www.youtube.com/xml/schemas/2015"
        atom_ns = "http://www.w3.org/2005/Atom"
        session = requests.Session()
        session.headers.update({"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/153 Safari/537.36"})

        for channel_url in urls:
            channel_id = ""
            m = re.search(r"youtube(?:-nocookie)?\.com/channel/(UC[\w-]{15,})", channel_url, re.I)
            if m:
                channel_id = m.group(1)
            else:
                try:
                    resp = session.get(channel_url, timeout=15, allow_redirects=True)
                    resp.raise_for_status()
                    html = resp.text or ""
                    patterns = [
                        r'"channelId"\s*:\s*"(UC[\w-]{15,})"',
                        r'"externalId"\s*:\s*"(UC[\w-]{15,})"',
                        r'<meta[^>]+itemprop=["\']channelId["\'][^>]+content=["\'](UC[\w-]{15,})["\']',
                    ]
                    for pat in patterns:
                        mm = re.search(pat, html, re.I)
                        if mm:
                            channel_id = mm.group(1)
                            break
                except Exception as exc:
                    workflow_cmd_log("GEMINI", "YOUTUBE_CHANNEL_PAGE_RESOLVE_FAIL",
                                     project=project or "", channel=channel_url,
                                     error=str(exc)[:700], level="WARN", pct=24)

            if not channel_id:
                workflow_cmd_log("GEMINI", "YOUTUBE_CHANNEL_ID_NOT_FOUND",
                                 project=project or "", channel=channel_url,
                                 level="WARN", pct=24)
                continue

            feed_url = f"https://www.youtube.com/feeds/videos.xml?channel_id={channel_id}"
            try:
                resp = session.get(feed_url, timeout=15)
                resp.raise_for_status()
                root = ET.fromstring(resp.content)
                found_for_channel = []
                for entry in root.findall(f"{{{atom_ns}}}entry"):
                    vid = entry.find(f"{{{yt_ns}}}videoId")
                    if vid is None or not str(vid.text or "").strip():
                        continue
                    video_id = str(vid.text).strip()
                    video_url = f"https://www.youtube.com/watch?v={video_id}"
                    if video_url not in found_for_channel:
                        found_for_channel.append(video_url)
                    if len(found_for_channel) >= 3:
                        break
                for video_url in found_for_channel:
                    if video_url not in out:
                        out.append(video_url)
                workflow_cmd_log("GEMINI", "YOUTUBE_CHANNEL_RSS_OK",
                                 project=project or "", channel=channel_url,
                                 channel_id=channel_id, video_count=len(found_for_channel),
                                 videos=" | ".join(found_for_channel), pct=29)
            except Exception as exc:
                workflow_cmd_log("GEMINI", "YOUTUBE_CHANNEL_RSS_FAIL",
                                 project=project or "", channel=channel_url,
                                 channel_id=channel_id, error=str(exc)[:700], level="WARN", pct=24)

        out = out[:6]
        if out:
            workflow_cmd_log("GEMINI", "YOUTUBE_CHANNEL_SEARCH_OK",
                             project=project or "", channel_count=len(urls),
                             video_count=len(out), videos=" | ".join(out), pct=30)
        else:
            workflow_cmd_log("GEMINI", "YOUTUBE_CHANNEL_SEARCH_FAIL",
                             project=project or "", error="Không resolve được video public từ channel RSS.",
                             level="WARN", pct=24)
        return out
    except Exception as exc:
        workflow_cmd_log("GEMINI", "YOUTUBE_CHANNEL_SEARCH_FAIL",
                         project=project or "", error=str(exc)[:1200], level="WARN", pct=24)
        return []


def _gemini_api_generate(prompt, reference_images=None, response_mode=None, project=None,
                         response_validator=None, max_attempts=3, url_context_urls=None):
    """Single Gemini transport: official API + File API, with key rotation/retry.

    No browser automation, DOM upload, clipboard, tab focus, Playwright or CDP is used here.
    Reference images are uploaded directly to Gemini File API (max 3 per request).
    """
    global _GEMINI_KEY_INDEX, _GEMINI_LAST_STRUCTURED_RESULT
    keys = _load_gemini_keys()
    ui_key = str(SETTINGS.get("gemini_api_key", "") or "").strip()
    if ui_key and ui_key not in keys:
        keys.insert(0, ui_key)
    if not keys:
        raise RuntimeError(
            'Chưa có Gemini API key. Hãy nhập API Key trong ⚙ Môi trường hoặc thêm key vào gemini_keys.json.'
        )
    if GEMINI_MODEL_API_SHUTDOWN:
        workflow_cmd_log(
            'GEMINI', 'MODEL_UNAVAILABLE', project=project or '',
            model=GEMINI_MODEL, level='ERROR', pct=0,
            error=f'Model Gemini {GEMINI_MODEL} đang bị đánh dấu shutdown trong cấu hình.'
        )
        raise RuntimeError(
            f'Model Gemini `{GEMINI_MODEL}` đang bị đánh dấu shutdown trong cấu hình; '
            'kiểm tra GEMINI_MODEL trước khi chạy workflow.'
        )
    try:
        from google import genai
    except Exception as exc:
        workflow_cmd_log("GEMINI","DEPENDENCY_MISSING",project=project or "",package="google-genai",level="ERROR",pct=0,error=str(exc)[:800])
        raise RuntimeError("Thiếu `google-genai`. Hãy cài dependency trong Environment/Setup trước khi chạy Workflow; Master không tự pip-install giữa chừng.") from exc

    # google-genai is bootstrapped above when missing, so import its types exactly once
    # per API call rather than repeatedly inside retry/URL branches.
    from google.genai import types

    url_context_urls = [str(u).strip() for u in (url_context_urls or []) if str(u).strip()]
    url_context_urls = list(dict.fromkeys(url_context_urls))[:10]
    # URL Context does NOT support YouTube video URLs. Public YouTube videos are
    # supported as direct video inputs to Gemini, so route watch/shorts/youtu.be
    # links through video understanding instead of the URL Context verifier.
    youtube_video_urls = []
    youtube_channel_urls = []
    non_youtube_url_context_urls = []
    for _u in url_context_urls:
        _lu = _u.lower()
        if ('youtube.com/watch?' in _lu or 'youtube.com/shorts/' in _lu or
                'youtu.be/' in _lu):
            youtube_video_urls.append(_u)
        elif 'youtube.com/' in _lu or 'youtube-nocookie.com/' in _lu:
            youtube_channel_urls.append(_u)
        else:
            non_youtube_url_context_urls.append(_u)
    if youtube_video_urls:
        workflow_cmd_log('GEMINI', 'YOUTUBE_VIDEO_INPUT_READY', project=project or '',
                         count=len(youtube_video_urls), urls=' | '.join(youtube_video_urls), level='INFO')
    # A channel URL is only a discovery seed. Resolve it BEFORE the real B1 request
    # so the main Gemini call receives concrete public video URLs as native video inputs.
    # Keep the original channel URLs in the competitor gate, but never pretend the channel
    # page itself was inspected as a URL-Context document.
    discovered_channel_video_urls = []
    if youtube_channel_urls:
        workflow_cmd_log('GEMINI', 'YOUTUBE_CHANNEL_URL_CONTEXT_UNSUPPORTED', project=project or '',
                         count=len(youtube_channel_urls), urls=' | '.join(youtube_channel_urls),
                         level='INFO')
        discovered_channel_video_urls = _gemini_channel_search_tool_urls(youtube_channel_urls, project=project)
        for _du in discovered_channel_video_urls:
            if _du not in youtube_video_urls:
                youtube_video_urls.append(_du)
        if discovered_channel_video_urls:
            workflow_cmd_log(
                'GEMINI', 'YOUTUBE_CHANNEL_VIDEOS_READY', project=project or '',
                channel_count=len(youtube_channel_urls), video_count=len(discovered_channel_video_urls),
                videos=' | '.join(discovered_channel_video_urls), level='INFO', pct=30
            )
        else:
            workflow_cmd_log(
                'GEMINI', 'YOUTUBE_CHANNEL_VIDEOS_NOT_FOUND', project=project or '',
                channel_count=len(youtube_channel_urls), channels=' | '.join(youtube_channel_urls),
                level='WARN', pct=24
            )
    # Only non-YouTube web URLs go through URL Context and its strict retrieval gate.
    url_context_urls = non_youtube_url_context_urls
    refs = []
    for item in list(reference_images or [])[:3]:
        fp = Path(str(item.get('path') if isinstance(item, dict) else item)).expanduser()
        if not fp.is_file():
            raise FileNotFoundError(f'Không tìm thấy ảnh tham chiếu: {fp}')
        if fp.suffix.lower() not in SUPPORTED_IMAGE:
            raise RuntimeError(f'Ảnh tham chiếu không được hỗ trợ: {fp.name}')
        refs.append(fp)

    max_attempts = max(1, min(3, int(max_attempts or 3)))
    last_exc = None
    local_attempt = 0

    while local_attempt < max_attempts:
        local_attempt += 1
        with _GEMINI_KEY_LOCK:
            cursor=int(getattr(_GEMINI_KEY_CURSOR,"index",_GEMINI_KEY_INDEX) or 0)
            index=cursor % len(keys)
        client = None
        uploaded = []
        try:
            workflow_cmd_log(
                'GEMINI', 'API_ATTEMPT_START', project=project or '',
                attempt=local_attempt, max_attempts=max_attempts,
                key_index=index + 1, key_count=len(keys),
                reference_count=len(refs), response_mode=response_mode or '',
                transport='Gemini File API' if refs else 'Gemini API', pct=10,
            )
            # Hard network deadline: never let Gemini File/API calls hang the whole workflow.
            # google-genai HttpOptions.timeout is milliseconds.
            GEMINI_HTTP_TIMEOUT_MS = 60_000
            # URL Context gets a shorter hard deadline so a broken source/tool
            # cannot stall the whole Master chain for minutes.
            GEMINI_URL_CONTEXT_TIMEOUT_MS = 45_000
            client = genai.Client(
                api_key=keys[index],
                http_options=types.HttpOptions(timeout=GEMINI_HTTP_TIMEOUT_MS),
            )
            workflow_cmd_log(
                'GEMINI', 'API_TRANSPORT_READY', project=project or '',
                timeout_ms=GEMINI_HTTP_TIMEOUT_MS, key_index=index + 1,
                transport='Gemini File API' if refs else 'Gemini API', pct=12,
            )
            contents = []
            ref_names = []
            for n, fp in enumerate(refs, 1):
                workflow_cmd_log(
                    'GEMINI', 'REFERENCE_FILE_UPLOAD', project=project or '',
                    reference_index=n, reference_total=len(refs), filename=fp.name,
                    key_index=index + 1, pct=15 + int((n - 1) / max(1, len(refs)) * 10),
                )
                workflow_cmd_log(
                    'GEMINI', 'REFERENCE_UPLOAD_WAIT', project=project or '',
                    reference_index=n, reference_total=len(refs), filename=fp.name,
                    timeout_ms=GEMINI_HTTP_TIMEOUT_MS,
                )
                remote = client.files.upload(file=str(fp))
                uploaded.append(remote)
                workflow_cmd_log(
                    'GEMINI', 'REFERENCE_UPLOAD_OK', project=project or '',
                    reference_index=n, reference_total=len(refs), filename=fp.name,
                    pct=25,
                )
                contents.append(remote)
                ref_names.append(fp.name)
            # Normalize response mode before any prompt/config branch uses it.
            # This MUST happen before the YouTube channel discovery prompt below.
            _response_mode = str(response_mode or "").strip().lower()
            # On retries, explicitly reinforce the machine-readable contract.
            # The API response_schema should already enforce JSON, but if a model/runtime
            # still returns prose, the next attempt must be told to correct that format.
            effective_prompt = str(prompt)
            if local_attempt > 1 and str(response_mode or "").strip().lower() == "topic_style":
                effective_prompt += (
                    "\n\nFORMAT CORRECTION — PREVIOUS ATTEMPT DID NOT PASS THE JSON GATE. "
                    "Return ONLY one valid JSON object matching the supplied schema. "
                    "No Markdown fences, no prose, no commentary, no explanation before or after JSON."
                )
            # Public YouTube videos are passed as native video inputs. This is the
            # supported Gemini path for YouTube; URL Context explicitly excludes
            # YouTube videos. Channel URLs remain prompt-only and must not be
            # represented as if they were retrieved web pages.
            for _yt_url in youtube_video_urls:
                try:
                    contents.append(types.Part(file_data=types.FileData(file_uri=_yt_url)))
                    workflow_cmd_log('GEMINI', 'YOUTUBE_VIDEO_INPUT_ATTACHED',
                                     project=project or '', url=_yt_url, pct=27)
                except Exception as _yt_exc:
                    workflow_cmd_log('GEMINI', 'YOUTUBE_VIDEO_INPUT_FAIL',
                                     project=project or '', url=_yt_url, error=str(_yt_exc)[:900],
                                     level='ERROR', pct=0)
                    raise RuntimeError(f'Không thể gắn YouTube video vào Gemini: {_yt_url} — {str(_yt_exc)[:700]}') from _yt_exc
            if youtube_channel_urls and discovered_channel_video_urls and _response_mode == "topic_style":
                effective_prompt += (
                    "\n\nYOUTUBE CHANNEL DISCOVERY RESULT — these are public video URLs discovered from the supplied channel URL(s). "
                    "Analyze the attached video inputs as the competitor evidence. Do not claim to have inspected the channel page itself. "
                    "Use multiple videos when available and base competitor_style_confirmed/evidence on what is actually visible in those videos. "
                    "DISCOVERED VIDEO URLS:\n" + "\n".join(f"- {u}" for u in discovered_channel_video_urls)
                )
            elif youtube_channel_urls and _response_mode == "topic_style":
                effective_prompt += (
                    "\n\nYOUTUBE CHANNEL DISCOVERY: no specific public video URL was resolved from the supplied channel URL(s). "
                    "Do not pretend the channel page was inspected. Set competitor_style_confirmed to false and explain the limitation in competitor_evidence."
                )
            contents.append(effective_prompt)

            # Strict model diagnostic: do NOT silently fallback to another model.
            # This is especially important because GEMINI_MODEL is intentionally pinned to the active production model.
            try:
                workflow_cmd_log(
                    'GEMINI', 'MODEL_CHECK_START', project=project or '',
                    model=GEMINI_MODEL, key_index=index + 1, pct=28,
                )
                model_info = client.models.get(model=GEMINI_MODEL)
                model_name = str(getattr(model_info, 'name', '') or GEMINI_MODEL)
                workflow_cmd_log(
                    'GEMINI', 'MODEL_CHECK_OK', project=project or '',
                    model=model_name, key_index=index + 1, pct=29,
                )
            except Exception as model_exc:
                model_error = str(model_exc).strip()
                workflow_cmd_log(
                    'GEMINI', 'MODEL_CHECK_FAIL', project=project or '',
                    model=GEMINI_MODEL, key_index=index + 1,
                    error=model_error[:1400], level='ERROR', pct=0,
                )
                raise RuntimeError(
                    f"Model Gemini `{GEMINI_MODEL}` không khả dụng với API key hiện tại. "
                    f"Không tự đổi sang model khác. Chi tiết: {model_error[:1000]}"
                ) from model_exc

            workflow_cmd_log(
                'GEMINI', 'API_REQUEST', project=project or '',
                key_index=index + 1, key_count=len(keys),
                reference_count=len(ref_names),
                reference_files=' | '.join(ref_names),
                response_mode=response_mode or '',
                url_context_count=len(url_context_urls),
                transport='Gemini File API' if refs else 'Gemini API', pct=30,
            )
            workflow_cmd_log(
                'GEMINI', 'API_REQUEST_WAIT', project=project or '',
                key_index=index + 1, timeout_ms=(GEMINI_URL_CONTEXT_TIMEOUT_MS if url_context_urls else GEMINI_HTTP_TIMEOUT_MS),
                response_mode=response_mode or '', pct=31,
            )
            # Always initialize the request config before branching.
            # Without this, Python treats `config` as a local variable because it is
            # assigned inside the URL-context branch, then the normal branch can raise
            # UnboundLocalError: cannot access local variable 'config'.
            config_kwargs = {
                "automatic_function_calling": types.AutomaticFunctionCallingConfig(disable=True),
            }
            # B1 is a classification contract, not free-form prose. Gemini supports
            # JSON Schema structured output; keep this schema only for the topic/style stage.
            if _response_mode == "topic_style":
                config_kwargs.update({
                    "response_mime_type": "application/json",
                    "response_schema": _gemini_topic_profile_schema(),
                })
            elif _response_mode == "batch":
                config_kwargs.update({
                    "response_mime_type": "application/json",
                    "response_schema": _gemini_b2_scene_schema(),
                })
            config = types.GenerateContentConfig(**config_kwargs)
            _channel_search_needed = bool(youtube_channel_urls and not discovered_channel_video_urls)
            if url_context_urls or _channel_search_needed:
                # Non-YouTube web URLs use URL Context. If explicit channel discovery
                # failed, allow the main B1 request one final Google Search attempt.
                # When discovery succeeded, the concrete video inputs are already attached.
                # URLs remain in the prompt so Gemini knows exactly which sources to inspect,
                # while the built-in tool performs the actual retrieval.
                try:
                    workflow_cmd_log(
                        'GEMINI', 'URL_CONTEXT_REQUEST_START', project=project or '',
                        key_index=index + 1, url_count=len(url_context_urls),
                        timeout_ms=GEMINI_URL_CONTEXT_TIMEOUT_MS, pct=32,
                    )
                    _tools = []
                    if url_context_urls:
                        _tools.append(types.Tool(url_context=types.UrlContext()))
                    if _channel_search_needed:
                        _tools.append(types.Tool(google_search=types.GoogleSearch()))
                    url_config_kwargs = {
                        "tools": _tools,
                        "automatic_function_calling": types.AutomaticFunctionCallingConfig(disable=True),
                    }
                    if _response_mode == "topic_style":
                        url_config_kwargs.update({
                            "response_mime_type": "application/json",
                            "response_schema": _gemini_topic_profile_schema(),
                        })
                    elif _response_mode == "batch":
                        url_config_kwargs.update({
                            "response_mime_type": "application/json",
                            "response_schema": _gemini_b2_scene_schema(),
                        })
                    config = types.GenerateContentConfig(**url_config_kwargs)
                    # The client-wide timeout is the actual transport deadline.
                    # Keep this request isolated so a URL Context failure is handled
                    # by the key-failover path below rather than blocking Master.
                    result = client.models.generate_content(model=GEMINI_MODEL, contents=contents, config=config)
                    workflow_cmd_log(
                        'GEMINI', 'COMPETITOR_TOOLS_REQUEST_OK', project=project or '',
                        key_index=index + 1,
                        url_context_count=len(url_context_urls),
                        youtube_channel_search_count=int(_channel_search_needed),
                        pct=68,
                    )
                except Exception as tool_exc:
                    workflow_cmd_log(
                        'GEMINI', 'COMPETITOR_TOOLS_REQUEST_FAIL', project=project or '',
                        key_index=index + 1,
                        url_context_count=len(url_context_urls),
                        youtube_channel_search_count=int(_channel_search_needed),
                        error=str(tool_exc)[:1200], level='ERROR', pct=0,
                    )
                    # Mark this as a key/transport-rotatable failure. With multiple
                    # keys, immediately move to the next key instead of retrying the
                    # same broken URL Context path. With one key, fail fast and tell
                    # the user exactly which capability failed.
                    raise _GeminiExplicitResponseError(
                        'Gemini không truy xuất được công cụ nguồn đối thủ; không được giả định đã đọc URL.',
                        retryable=False, mode=response_mode or ''
                    ) from tool_exc
            else:
                safe_config = config
                result = client.models.generate_content(model=GEMINI_MODEL, contents=contents, config=safe_config)
            if SCRIPT_STOP_EVENT.is_set() or FULL_STOP_EVENT.is_set() or PROMPT_STOP_EVENT.is_set():
                raise RuntimeError("Gemini request đã hoàn tất nhưng workflow đã nhận STOP; không tiếp tục parse/lưu dữ liệu.")
            workflow_cmd_log(
                'GEMINI', 'API_RESPONSE_RECEIVED', project=project or '',
                key_index=index + 1, pct=70,
            )
            value = (getattr(result, 'text', None) or '').strip()

            # Parse the structured response BEFORE running the validator. Earlier versions
            # validated against _GEMINI_LAST_STRUCTURED_RESULT before publishing the freshly
            # received response, which could reject an otherwise valid B1 response.
            parsed_response = None
            parsed_response_source = 'none'
            if value:
                try:
                    parsed_response = json.loads(value)
                    parsed_response_source = 'direct_json'
                except Exception:
                    # Accept fenced JSON and JSON embedded in a small amount of prose as a
                    # diagnostic/recovery path. We still require the final object to satisfy
                    # the response validator; plain prose is never silently accepted as B1.
                    for candidate in re.findall(r'```(?:json|javascript|text)?\s*(.*?)\s*```', value, re.I | re.S):
                        try:
                            parsed_response = json.loads(candidate.strip())
                            parsed_response_source = 'fenced_json'
                            break
                        except Exception:
                            pass
                    if parsed_response is None:
                        decoder = json.JSONDecoder()
                        for m in re.finditer(r'\{', value):
                            try:
                                obj, _end = decoder.raw_decode(value[m.start():])
                                parsed_response = obj
                                parsed_response_source = 'embedded_json'
                                break
                            except Exception:
                                pass

            if parsed_response is not None:
                workflow_cmd_log(
                    'GEMINI', 'RESPONSE_FORMAT_JSON', project=project or '',
                    source=parsed_response_source,
                    top_type=type(parsed_response).__name__,
                    top_keys=' | '.join(str(k) for k in parsed_response.keys()) if isinstance(parsed_response, dict) else '',
                    pct=72,
                )
                if isinstance(parsed_response, dict):
                    if str(response_mode or '').strip().lower() == 'topic_style':
                        _GEMINI_LAST_STRUCTURED_RESULT = {'topic_style': parsed_response}
                    else:
                        _GEMINI_LAST_STRUCTURED_RESULT = parsed_response
            else:
                preview = re.sub(r'\s+', ' ', value)[:1200]
                if str(response_mode or '').strip().lower() == 'scene_split':
                    workflow_cmd_log(
                        'GEMINI', 'RESPONSE_FORMAT_SCENE_TAGS', project=project or '',
                        response_type='scene_tagged_text', chars=len(value), preview=preview,
                        level='INFO', pct=72,
                    )
                else:
                    workflow_cmd_log(
                        'GEMINI', 'RESPONSE_FORMAT_NOT_JSON', project=project or '',
                        response_type='text', chars=len(value), preview=preview,
                        level='WARN', pct=72,
                    )
            if not value:
                candidates = getattr(result, 'candidates', None) or []
                prompt_feedback = getattr(result, 'prompt_feedback', None)
                block_reason = str(getattr(prompt_feedback, 'block_reason', '') or '').strip()
                safety_rows = []
                for candidate in candidates:
                    finish_reason = str(getattr(candidate, 'finish_reason', '') or '').strip()
                    finish_message = str(getattr(candidate, 'finish_message', '') or '').strip()
                    ratings = getattr(candidate, 'safety_ratings', None) or []
                    rating_text = []
                    for rating in ratings:
                        category = str(getattr(rating, 'category', '') or '').strip()
                        probability = str(getattr(rating, 'probability', '') or '').strip()
                        blocked = getattr(rating, 'blocked', None)
                        rating_text.append(f"{category}:{probability}:blocked={blocked}")
                    safety_rows.append({"finish_reason": finish_reason, "finish_message": finish_message, "safety": rating_text})
                if block_reason or any(str(x.get('finish_reason','')).upper() in {'SAFETY','PROHIBITED_CONTENT','BLOCKLIST','SPII','RECITATION'} for x in safety_rows):
                    detail = json.dumps({"prompt_block_reason": block_reason, "candidates": safety_rows}, ensure_ascii=False)[:5000]
                    workflow_cmd_log('GEMINI', 'CONTENT_BLOCKED', project=project or '', level='ERROR', reason=block_reason or 'candidate_finish_reason', detail=detail, pct=0)
                    raise _GeminiExplicitResponseError(
                        f"Gemini đã chặn nội dung theo safety/content policy. Chi tiết API: {detail}",
                        retryable=False, mode=response_mode or ''
                    )
                model_version = str(getattr(result, 'model_version', '') or '').strip()
                response_id = str(getattr(result, 'response_id', '') or '').strip()
                usage = getattr(result, 'usage_metadata', None)
                total_tokens = getattr(usage, 'total_token_count', None) if usage is not None else None
                workflow_cmd_log(
                    'GEMINI', 'EMPTY_RESPONSE_DIAGNOSTIC', project=project or '', level='ERROR',
                    candidates_count=len(candidates), prompt_block_reason=block_reason or '',
                    finish_reasons=' | '.join(str(x.get('finish_reason','')) for x in safety_rows),
                    model_version=model_version, response_id=response_id,
                    total_tokens=total_tokens, pct=0,
                )
                raise RuntimeError(
                    'Gemini API không trả về nội dung; không có text/candidate content. '
                    f'candidates={len(candidates)} block_reason={block_reason or "none"} '
                    f'finish_reason={" | ".join(str(x.get("finish_reason", "")) for x in safety_rows) or "none"} '
                    f'model={model_version or "unknown"} response_id={response_id or "unknown"}'
                )

            if response_validator is not None:
                workflow_cmd_log('GEMINI', 'RESPONSE_VALIDATE_START', project=project or '', pct=75)
                try:
                    valid = bool(response_validator(value))
                except Exception as validator_exc:
                    valid = False
                    last_exc = validator_exc
                if not valid:
                    if parsed_response is None:
                        detail = (
                            'Gemini trả text thay vì JSON hợp lệ. '
                            'Đã thử JSON trực tiếp, fenced JSON và JSON embedded nhưng không parse được.'
                        )
                    elif isinstance(parsed_response, dict):
                        detail = (
                            'Gemini trả JSON nhưng không vượt qua Scene/Topic schema gate. '
                            f'Các field nhận được: {", ".join(str(k) for k in parsed_response.keys())}'
                        )
                    else:
                        detail = f'Gemini trả JSON kiểu {type(parsed_response).__name__}, không phải object.'
                    workflow_cmd_log(
                        'GEMINI', 'RESPONSE_GATE_FAIL', project=project or '',
                        response_mode=response_mode or '', detail=detail[:1800],
                        level='WARN', pct=0,
                    )
                    raise _GeminiExplicitResponseError(
                        detail, retryable=True, mode=response_mode or ''
                    )
                workflow_cmd_log('GEMINI', 'RESPONSE_VALIDATE_OK', project=project or '', pct=85)

            with _GEMINI_KEY_LOCK:
                _GEMINI_KEY_INDEX=index
                _GEMINI_KEY_CURSOR.index=index
            if url_context_urls:
                metadata = None
                try:
                    candidates = getattr(result, 'candidates', None) or []
                    if candidates:
                        metadata = getattr(candidates[0], 'url_context_metadata', None)
                except Exception:
                    metadata = None
                # Google documents url_context_metadata.url_metadata[].retrieved_url as
                # the authoritative retrieval record. The previous implementation only
                # regexed str(metadata), which can miss values on SDK model objects and
                # falsely reject a successful URL Context retrieval.
                retrieved = []
                import re as _re

                def _collect_retrieved_urls(obj):
                    found_urls = []
                    seen = set()

                    def add_url(value):
                        if not value:
                            return
                        value = str(value).strip().rstrip('.,);]')
                        if value.startswith(('http://', 'https://')) and value not in seen:
                            seen.add(value)
                            found_urls.append(value)

                    def walk(value, depth=0):
                        if value is None or depth > 8:
                            return
                        if isinstance(value, str):
                            for found in _re.findall(r'https?://[^\s\"\'<>]+', value):
                                add_url(found)
                            return
                        if isinstance(value, dict):
                            for key, val in value.items():
                                if str(key).lower() in {'retrieved_url', 'url', 'source_url'}:
                                    add_url(val)
                                walk(val, depth + 1)
                            return
                        if isinstance(value, (list, tuple, set)):
                            for item in value:
                                walk(item, depth + 1)
                            return
                        # google-genai Pydantic models
                        try:
                            dumped = value.model_dump()
                            walk(dumped, depth + 1)
                            return
                        except Exception:
                            pass
                        try:
                            dumped = value.to_dict()
                            walk(dumped, depth + 1)
                            return
                        except Exception:
                            pass
                        for attr in ('retrieved_url', 'url', 'source_url', 'url_metadata'):
                            try:
                                attr_value = getattr(value, attr, None)
                            except Exception:
                                attr_value = None
                            if attr_value is not None:
                                if attr in ('retrieved_url', 'url', 'source_url'):
                                    add_url(attr_value)
                                else:
                                    walk(attr_value, depth + 1)

                    walk(obj)
                    return found_urls

                retrieved = _collect_retrieved_urls(metadata)

                matched = [
                    u for u in url_context_urls
                    if any(
                        u == r
                        or u.rstrip('/') == r.rstrip('/')
                        or u.rstrip('/') in r
                        or r.rstrip('/') in u
                        for r in retrieved
                    )
                ]
                if not matched:
                    workflow_cmd_log(
                        'GEMINI', 'URL_CONTEXT_VERIFY_FAIL',
                        project=project or '',
                        requested=' | '.join(url_context_urls),
                        retrieved=' | '.join(retrieved[:20]),
                        metadata_type=type(metadata).__name__ if metadata is not None else 'None',
                        level='ERROR',
                    )
                    raise _GeminiExplicitResponseError(
                        'Gemini không cung cấp bằng chứng URL Context đã truy xuất nguồn đối thủ.',
                        retryable=True, mode=response_mode or ''
                    )
                workflow_cmd_log(
                    'GEMINI', 'URL_CONTEXT_VERIFY_OK',
                    project=project or '',
                    requested_count=len(url_context_urls),
                    matched_count=len(matched),
                    matched=' | '.join(matched),
                    pct=70,
                )
            elif youtube_video_urls or youtube_channel_urls:
                workflow_cmd_log(
                    'GEMINI', 'YOUTUBE_COMPETITOR_INPUT_OK',
                    project=project or '',
                    video_count=len(youtube_video_urls),
                    channel_count=len(youtube_channel_urls),
                    video_urls=' | '.join(youtube_video_urls),
                    channel_urls=' | '.join(youtube_channel_urls),
                    note='YouTube video links were supplied as native video inputs; channel URLs are prompt-only.',
                    pct=70,
                )
            workflow_cmd_log(
                'GEMINI', 'API_RESPONSE_OK', project=project or '',
                key_index=index + 1, chars=len(value),
                transport='Gemini File API' if refs else 'Gemini API', pct=95,
            )
            return value

        except Exception as exc:
            last_exc = exc
            rotatable = _gemini_key_error_is_rotatable(exc)
            transient = _gemini_transient_error(exc)
            can_retry = local_attempt < max_attempts
            url_context_failure = (
                bool(url_context_urls)
                and isinstance(exc, _GeminiExplicitResponseError)
                and 'URL Context' in str(exc)
            )
            if url_context_failure and len(keys) > 1 and can_retry:
                nxt_index = (index + 1) % len(keys)
                workflow_cmd_log(
                    'GEMINI', 'GEMINI URL_CONTEXT KEY ROTATE %d -> %d' % (index + 1, nxt_index + 1),
                    project=project or '', reason=str(exc)[:700],
                    key_count=len(keys), attempt=local_attempt, pct=25,
                )
                with _GEMINI_KEY_LOCK:
                    _GEMINI_KEY_INDEX=nxt_index
                    _GEMINI_KEY_CURSOR.index=nxt_index
                continue
            if rotatable and len(keys) > 1:
                nxt_index = (index + 1) % len(keys)
                workflow_cmd_log(
                    'GEMINI', 'GEMINI KEY ROTATE %d -> %d' % (index + 1, nxt_index + 1),
                    project=project or '', reason=str(exc)[:500],
                    key_count=len(keys), attempt=local_attempt, pct=25,
                )
                with _GEMINI_KEY_LOCK:
                    _GEMINI_KEY_INDEX=nxt_index
                    _GEMINI_KEY_CURSOR.index=nxt_index
                continue
            if can_retry and (transient or isinstance(exc, _GeminiExplicitResponseError)):
                workflow_cmd_log(
                    'GEMINI', 'API_RETRY_SAME_KEY', project=project or '',
                    key_index=index + 1, attempt=local_attempt + 1,
                    max_attempts=max_attempts, reason=str(exc)[:500], pct=30,
                )
                time.sleep(min(2.0 * local_attempt, 5.0))
                continue
            workflow_cmd_log(
                'GEMINI', 'API_REQUEST_FAIL', project=project or '',
                key_index=index + 1, attempt=local_attempt,
                error=str(exc)[:1200], level='ERROR', pct=0,
            )
            raise
        finally:
            for remote in uploaded:
                try:
                    name = getattr(remote, 'name', None)
                    if client is not None and name and hasattr(client.files, 'delete'):
                        client.files.delete(name=name)
                except Exception:
                    pass
            if client is not None:
                try:
                    client.close()
                except Exception:
                    pass

    raise last_exc or RuntimeError('Gemini API workflow thất bại.')




def _gemini_api_text(prompt: str, completion_marker=None, response_mode=None, reference_images=None,
                      response_validator=None, max_attempts=2, url_context_urls=None) -> str:
    """Small API-only text helper used by Gemini workflow callbacks."""
    project = safe_name(str(SETTINGS.get('selected_project', '') or ''))
    if _master_is_stopped() or FULL_STOP_EVENT.is_set() or PROMPT_STOP_EVENT.is_set():
        raise RuntimeError('⏹ Gemini API bị dừng bởi MASTER STOP.')
    value = _gemini_api_generate(
        prompt,
        reference_images=list(reference_images or [])[:3],
        response_mode=response_mode,
        project=project,
        response_validator=response_validator,
        max_attempts=max_attempts,
        url_context_urls=url_context_urls,
    )
    if completion_marker and completion_marker not in value:
        workflow_cmd_log('GEMINI', 'COMPLETION_MARKER_MISSING', project=project, marker=completion_marker, level='WARN')
    workflow_cmd_log('GEMINI', 'STAGE_COMPLETE', project=project, response_mode=response_mode or '', pct=100)
    return value.strip()


_ensure_gemini_keys_file()

def _ensure_project_workflow_tree(project: str) -> Path:
    root = project_dir(project)
    if not PROJECT_CONNECTED:
        raise RuntimeError(f"Project `{project}` chưa được kết nối. Hãy bấm **Mở folder có sẵn** hoặc **Tạo & Kết nối Project** trước khi chạy workflow.")
    if not root.exists() or not root.is_dir():
        raise RuntimeError(f"Không tìm thấy Project root đã kết nối: `{root}`")

    # Source of truth: exactly 3 top-level Project folders.
    _migrate_legacy_project_layout(root)
    for d in (_project_content_dir(root), _project_media_dir(root), _project_export_dir(root)):
        d.mkdir(parents=True, exist_ok=True)
    for d in (
        _project_content_dir(root) / "Kịch bản",
        _project_content_dir(root) / "Cảnh",
        _project_content_dir(root) / "Prompt",
        _project_media_dir(root) / "Hình ảnh",
        _project_media_dir(root) / "Âm thanh" / "Cảnh",
        _project_media_dir(root) / "Âm thanh" / "Voice Full",
        _project_export_dir(root) / "Phụ đề",
        _project_export_dir(root) / "Dòng thời gian",
        _project_export_dir(root) / "QC",
        _project_export_dir(root) / "CapCut",
    ):
        d.mkdir(parents=True, exist_ok=True)

    # Z-Image workflow is shared/tool-owned and manually imported into ComfyUI 8188.
    # Never create a duplicate workflow JSON inside the Project.
    return root

def _create_scenes_progress_steps(project: str,text: str,target_chars: int=320,start_pct: int=0,end_pct: int=100,media_mode=None):
    mode=normalize_media_mode(media_mode); SETTINGS["media_mode"]=mode; cleaned=re.sub(r"\s+"," ",(text or "").strip())
    if not cleaned:
        yield start_pct,[],"✕ Kịch bản đang trống — không tạo Scenes."; return
    target_chars=max(180,min(int(target_chars or 320),550)); max_chars=min(650,int(target_chars*1.45))
    def mp(x): return min(end_pct,start_pct+int((x/100.0)*(end_pct-start_pct)))
    root=_ensure_project_workflow_tree(project); (_project_content_dir(root)/"Kịch bản"/"script.txt").write_text(cleaned,encoding='utf-8'); write_json(_project_content_dir(root)/"Kịch bản"/"intelligence.json",script_intelligence(cleaned))
    yield mp(5),[],f"📥 Đã nhận kịch bản — chuẩn hóa nội dung... ({mp(5)}%)"
    sentences=[x.strip() for x in re.split(r"(?<=[.!?。！？])\s+",cleaned) if x.strip()]; pieces=[]
    for sentence in sentences: pieces.extend(_split_long_piece(sentence,max_chars))
    scenes=[]; current=""
    for piece in pieces:
        if not current: current=piece
        elif len(current)+len(piece)+1<=target_chars: current=(current+" "+piece).strip()
        else: scenes.append(current); current=piece
    if current: scenes.append(current)
    total=len(scenes); manifest=[]
    for i,value in enumerate(scenes,1):
        if SCRIPT_STOP_EVENT.is_set(): yield mp(45),[],"⏹ Đã dừng workflow trước khi ghi Scene tiếp theo."; return
        sid=f"Scene_{i:03d}"; explicit,value=scene_media_hint(value); media_type="image" if mode=="pure_images" else (explicit or "image"); source="pure_images" if mode=="pure_images" else ("explicit_tag" if explicit else "pending_gemini")
        (_project_content_dir(root)/"Cảnh"/f"{sid}.txt").write_text(value,encoding='utf-8'); manifest.append({"scene_id":sid,"text":value,"prompt":"","media_type":media_type,"media_type_source":source,"media_mode":mode})
        if i==1 or i==total or i%max(1,total//12)==0: yield mp(45+int(i/max(1,total)*50)),[[x["scene_id"],x["text"]] for x in manifest],f"📝 Đang ghi Scene {i}/{total} — {sid}"
    write_json(_project_content_dir(root)/"Cảnh"/"manifest.json",{"scenes":manifest,"target_chars":target_chars,"media_mode":mode}); save_settings(); yield end_pct,[[x["scene_id"],x["text"]] for x in manifest],f"✅ Chia cảnh hoàn tất: {total} scenes — 100%"

def script_intelligence(text: str):
    return {
        "word_count": len(re.findall(r"\b[\w'-]+\b", text or "", flags=re.UNICODE)),
        "dates": re.findall(r"\b(?:19|20)\d{2}\b|\b\d{1,2}[/-]\d{1,2}[/-]\d{2,4}\b", text or ""),
        "percentages": re.findall(r"\b\d+(?:\.\d+)?\s*%", text or ""),
        "ages": re.findall(r"\b(?:age|aged)\s*\d+\b|\b\d+\s*\+\b", text or "", flags=re.I),
        "numbers": re.findall(r"\b\d+(?:\.\d+)?\b", text or ""),
    }

def _split_long_piece(piece: str, max_chars: int):
    """Split long narration deterministically, including unbroken tokens/URLs.

    Never recurses on an unchanged string. Any token longer than max_chars is
    hard-sliced so a URL, hash, code string, or CJK run cannot trigger a
    recursion loop or produce an over-sized TTS chunk.
    """
    max_chars = max(1, int(max_chars or 320))
    piece = re.sub(r"\s+", " ", str(piece or "").strip())
    if not piece:
        return []
    if len(piece) <= max_chars:
        return [piece]

    parts = [p.strip() for p in re.split(r"(?<=[,;:—–-])\s+", piece) if p.strip()]
    if len(parts) <= 1:
        parts = piece.split()

    chunks, cur = [], ""
    for part in parts:
        # Hard split pathological unbroken tokens (URL/code/hash/etc.).
        if len(part) > max_chars:
            if cur:
                chunks.append(cur)
                cur = ""
            chunks.extend(part[i:i + max_chars] for i in range(0, len(part), max_chars))
            continue
        candidate = (cur + " " + part).strip() if cur else part
        if len(candidate) <= max_chars:
            cur = candidate
        else:
            if cur:
                chunks.append(cur)
            cur = part
    if cur:
        chunks.append(cur)
    return chunks


def load_manifest(project: str):
    if not str(project or '').strip(): return []
    root = project_dir(project)
    data = read_json(_project_scene_dir(root) / "manifest.json", {}) or {}
    raw = data.get("scenes", []) if isinstance(data, dict) else []
    normalized=[]
    for i,item in enumerate(raw):
        if isinstance(item, dict):
            sid=str(item.get("scene_id") or f"Scene_{i+1:03d}")
            item["scene_id"]=sid; item["text"]=str(item.get("text") or item.get("narration") or "")
            item["prompt"]=str(item.get("prompt") or item.get("image_prompt") or "")
            item["media_type"]=scene_media_type(item,"image")
            item["media_type_source"]=str(item.get("media_type_source") or "legacy")
            item["media_mode"]=normalize_media_mode(item.get("media_mode") or (data.get("media_mode") if isinstance(data,dict) else None))
            normalized.append(item)
        elif isinstance(item,(list,tuple)):
            normalized.append({"scene_id":str(item[0]) if len(item)>0 else f"Scene_{i+1:03d}","text":str(item[1]) if len(item)>1 else "","prompt":str(item[2]) if len(item)>2 else "","media_type":"image","media_type_source":"legacy","media_mode":"pure_images"})
    return normalized

def ensure_server_for_use(name: str):
    if not MANAGER.installed(name): raise RuntimeError(f"{ENGINE_INFO[name]['short']} chưa được cài.")
    if not MANAGER.health(name):
        status=MANAGER.start(name)
        if not MANAGER.health(name): raise RuntimeError(status)

def _is_vieneu_cuda_graph_error(detail: str) -> bool:
    low = str(detail or "").lower()
    needles = (
        "offset increment outside graph capture",
        "cudaerrorstreamcaptureinvalidated",
        "operation failed due to a previous error during capture",
        "operation not permitted when stream is capturing",
        "stream is capturing",
    )
    return any(x in low for x in needles)


def server_request(name: str, endpoint: str, payload: dict, timeout=1800):
    """POST to a TTS server with one hard recovery for CUDA-graph corruption.

    The TTS servers run in separate processes. If CUDA graph capture poisons
    the server's generator state, restarting that server is the safe reset;
    retrying in the same process is not.
    """
    url = ENGINE_INFO[name]["url"] + endpoint
    last_exc = None
    for attempt in range(2):
        try:
            r = requests.post(url, json=payload, timeout=timeout)
            if not r.ok:
                try:
                    detail = r.json().get("detail", r.text)
                except Exception:
                    detail = r.text
                detail = str(detail)
                if attempt == 0 and _is_vieneu_cuda_graph_error(detail):
                    workflow_cmd_log("VOICE", "TTS_CUDA_GRAPH_RECOVER", engine=name, endpoint=endpoint)
                    _master_cmd(f"Voice {ENGINE_INFO.get(name, {}).get('short', name)} gặp lỗi CUDA graph — đang khởi động lại server", "WARN")
                    try:
                        MANAGER.stop(name)
                    except Exception:
                        pass
                    gc.collect()
                    time.sleep(1.0)
                    status = MANAGER.start(name)
                    if str(status).startswith("✕"):
                        raise RuntimeError(status)
                    continue
                raise RuntimeError(detail)
            return r.json()
        except requests.exceptions.ConnectionError as exc:
            last_exc = exc
            if attempt == 0:
                workflow_cmd_log("VOICE", "TTS_CONNECTION_RECOVER", engine=name, endpoint=endpoint, error=str(exc)[:500])
                _master_cmd(f"Mất kết nối {ENGINE_INFO.get(name, {}).get('short', name)} — đang khởi động lại server", "WARN")
                try:
                    MANAGER.stop(name)
                except Exception:
                    pass
                gc.collect()
                time.sleep(1.0)
                status = MANAGER.start(name)
                if str(status).startswith("✕"):
                    raise RuntimeError(status)
                continue
            raise
        except RuntimeError as exc:
            last_exc = exc
            raise
    raise RuntimeError(str(last_exc or "TTS server không trả kết quả."))

def save_b64_audio(result: dict, target: Path):
    """Persist local TTS output with a path-first transport and bounded base64 decoding.

    Local engines may return a path directly; use it when available. The legacy
    audio_b64 contract remains supported, but is decoded in chunks so Python does
    not create a second full-size decoded bytes object before writing the WAV.
    """
    target = Path(target)
    target.parent.mkdir(parents=True, exist_ok=True)
    source_path = str((result or {}).get("audio_path") or (result or {}).get("path") or "").strip()
    if source_path and Path(source_path).is_file():
        src = Path(source_path)
        if src.resolve() != target.resolve():
            shutil.copyfile(src, target)
        return str(target)
    audio_url = str((result or {}).get("audio_url") or "").strip()
    if audio_url:
        with requests.get(audio_url, stream=True, timeout=300) as resp:
            resp.raise_for_status()
            with target.open("wb") as fh:
                for chunk in resp.iter_content(chunk_size=1024 * 1024):
                    if chunk:
                        fh.write(chunk)
        return str(target)
    encoded = str((result or {}).get("audio_b64") or "").strip()
    if not encoded:
        raise RuntimeError("Voice server không trả audio_path/audio_url/audio_b64.")
    import binascii
    carry = ""
    with target.open("wb") as fh:
        for start in range(0, len(encoded), 1024 * 1024):
            block = carry + encoded[start:start + 1024 * 1024]
            usable = len(block) - (len(block) % 4)
            if usable:
                try:
                    fh.write(binascii.a2b_base64(block[:usable]))
                except binascii.Error as exc:
                    raise RuntimeError(f"Audio base64 không hợp lệ: {exc}") from exc
            carry = block[usable:]
        if carry:
            try:
                fh.write(binascii.a2b_base64(carry))
            except binascii.Error as exc:
                raise RuntimeError(f"Audio base64 cuối file không hợp lệ: {exc}") from exc
    return str(target)

_VOICE_TRANSCRIPT_CACHE = {}

def create_voice(name: str, source: str, language: str, transcript: str):
    """Create one Clone Voice WAV directly in the voice library; no profile directory/json."""
    if not source:
        raise RuntimeError("Chọn voice mẫu trước.")
    src = Path(source).expanduser()
    if not src.is_file():
        raise RuntimeError("File voice mẫu không tồn tại.")
    raw_name = safe_name(Path(str(name or "My_Voice")).stem) or "My_Voice"
    VOICE_LIBRARY.mkdir(parents=True, exist_ok=True)
    target = VOICE_LIBRARY / f"{raw_name}.wav"
    ensure_server_for_use("cloneprep")
    result = server_request("cloneprep", "/prepare", {
        "source": str(src), "target": str(target), "language": language,
        "transcript": transcript or ""
    }, timeout=900)
    final_transcript = str((result or {}).get("transcript", transcript or ""))
    _VOICE_TRANSCRIPT_CACHE[str(target.resolve()).lower()] = final_transcript
    return str(target), final_transcript, f"✓ Voice '{target.name}' đã lưu thẳng vào thư mục `voice`."


def _voice_tuning_values(speed=None,pause_ms=None):
    try: spd=float(speed if speed is not None else SETTINGS.get("voice_speed",1.0))
    except Exception: spd=1.0
    try: pause=int(float(pause_ms if pause_ms is not None else SETTINGS.get("voice_pause_ms",180)))
    except Exception: pause=180
    return max(.75,min(1.5,spd)),max(0,min(1200,pause))

def _apply_voice_tuning(audio_path: Path,speed=None,pause_ms=None)->Path:
    speed,pause_ms=_voice_tuning_values(speed,pause_ms)
    if abs(speed-1.0)<.001 and pause_ms<=0: return audio_path
    try:
        import imageio_ffmpeg; ffmpeg=imageio_ffmpeg.get_ffmpeg_exe()
    except Exception: ffmpeg=shutil.which("ffmpeg")
    if not ffmpeg: return audio_path
    try:
        import soundfile as sf; duration=float(sf.info(str(audio_path)).duration)
    except Exception: duration=0.0
    if duration<=0: return audio_path
    out=audio_path.with_name(audio_path.stem+"_tuned.wav"); target_duration=max(.1,duration/speed+pause_ms/1000.0)
    filt=f"atempo={speed:.4f}" + (f",apad=pad_dur={pause_ms/1000.0:.3f}" if pause_ms>0 else "")
    r=subprocess.run([ffmpeg,"-y","-i",str(audio_path),"-filter:a",filt,"-t",f"{target_duration:.3f}","-ar","24000","-ac","1",str(out)],capture_output=True,text=True)
    # FFmpeg output can disappear between exists() and stat() on Windows
    # (AV/file-indexer/race). Never let that turn into a fake Voice-server
    # disconnect. If tuning failed, keep the original generated WAV.
    try:
        if r.returncode!=0 or not out.exists():
            return audio_path
        if out.stat().st_size < 100:
            return audio_path
    except (FileNotFoundError, OSError):
        return audio_path
    try:
        # FFmpeg already produced the final tuned WAV. Replace the original in
        # one filesystem operation instead of writing the tuned bytes a second
        # time with copy2 (raw -> tuned -> copied tuned).
        os.replace(str(out), str(audio_path))
    except Exception:
        try: out.unlink(missing_ok=True)
        except Exception: pass
        return audio_path
    return audio_path

def preview_tts(language,engine,voice,text,speed=None,pause_ms=None):
    selected=resolve_engine(language,engine); ensure_server_for_use(selected); ref,ref_text=voice_ref(voice)
    text=(text or "").strip() or ("Xin chào, đây là câu nghe thử." if language=="vi" else "Hello, this is a voice preview.")
    import tempfile
    out=Path(tempfile.gettempdir()) / f"vhung_voice_preview_{selected}_{os.getpid()}_{int(time.time()*1000)}.wav"
    speed,pause_ms=_voice_tuning_values(speed,pause_ms)
    result=server_request(selected,"/generate",{"text":text,"language_id":language,"ref_audio":ref,"ref_text":ref_text,"voice_id":"default"})
    save_b64_audio(result,out); _apply_voice_tuning(out,speed,pause_ms)
    return str(out),f"✓ Preview bằng {ENGINE_INFO[selected]['short']} xong · speed {speed:.2f}× · pause {pause_ms}ms."


def activate_voice_engine(language: str,engine: str):
    selected=route_engine(language) if engine=="auto" else engine
    if selected not in ENGINE_INFO: return selected,f"⚠ Engine không hợp lệ: {selected}"
    if selected=="chatterbox" and language not in CHATTERBOX_LANGS: return selected,f"⚠ Chatterbox không hỗ trợ {language_label(language)}."
    if selected=="vieneu" and language!="vi": return selected,"⚠ VieNeu được dành cho tiếng Việt / Việt-Anh."
    status=MANAGER.start(selected)
    if str(status).startswith("✕"): return selected,status
    gpu_ok, gpu_detail = verify_tts_gpu_runtime(selected)
    if not gpu_ok: return selected, f"⛔ TTS GPU GATE FAIL — {gpu_detail}"
    return selected,f"✅ Đã dùng {ENGINE_INFO[selected]['model']} — {ENGINE_INFO[selected]['title']} — {gpu_detail}"

def create_scenes_progress(project: str,text: str,target_chars: int=320,media_mode=None):
    yield from _create_scenes_progress_steps(project,text,target_chars,0,100,media_mode)

def voice_signature(language: str,engine: str,voice: str,script: str, scene_id: str = "")->str:
    """Return a deterministic signature for ONE voice-scene input.

    ``script`` is intentionally the scene narration, not the whole project
    script. This keeps the audio cache granular: editing Scene_099 invalidates
    Scene_099 only instead of forcing a 100-scene regeneration.
    """
    selected=resolve_engine(language,engine); ref,ref_text=voice_ref(voice)
    payload="|".join([selected,language,voice or "",ref or "",ref_text or "",str(scene_id or ""),script or "",str(SETTINGS.get("voice_speed",1.0)),str(SETTINGS.get("voice_pause_ms",180))])
    return hashlib.sha256(payload.encode("utf-8")).hexdigest()[:24]

def _cuda_check_python(py: Path):
    if not py.exists():
        return False, f"Không tìm thấy: {py}"
    code = "import torch; print('TORCH='+str(torch.__version__)); print('CUDA='+str(torch.cuda.is_available())); print('GPU='+(torch.cuda.get_device_name(0) if torch.cuda.is_available() else 'NONE'))"
    try:
        r=subprocess.run([str(py),"-c",code],capture_output=True,text=True,timeout=30)
        out=(r.stdout or "").strip(); err=(r.stderr or "").strip()
        if r.returncode!=0: return False, err[-1200:] or out[-1200:] or f"exit={r.returncode}"
        return "CUDA=True" in out,out
    except Exception as exc: return False,str(exc)

def _gpu_memory_by_pids(pids):
    """Return NVIDIA VRAM usage for TTS process IDs.

    Windows/WDDM can report a CUDA process as a graphics process rather than
    through ``--query-compute-apps``.  The old V43 gate treated that perfectly
    valid case as 0 MB and blocked Master.  Return an explicit attribution
    flag so the caller can use total GPU residency only as a fallback.
    """
    wanted = {str(int(x)) for x in (pids or []) if str(x).isdigit()}
    if not shutil.which("nvidia-smi"):
        return 0, {}, False
    try:
        r = subprocess.run(["nvidia-smi", "--query-compute-apps=pid,process_name,used_gpu_memory", "--format=csv,noheader,nounits"], capture_output=True, text=True, timeout=8)
        total, rows = 0, {}
        for line in (r.stdout or "").splitlines():
            parts = [x.strip() for x in line.split(",")]
            if len(parts) < 3 or parts[0] not in wanted: continue
            try: mb = int(float(re.sub(r"[^0-9.]", "", parts[2]) or 0))
            except Exception: mb = 0
            total += mb; rows[parts[0]] = {"process": parts[1], "vram_mb": mb}
        if total > 0:
            return total, rows, True

        # WDDM fallback: the driver may expose VRAM residency only at GPU level.
        # This does not falsely claim PID attribution; it only proves that the
        # NVIDIA device is actively holding VRAM while the managed TTS server is
        # healthy and its CUDA environment is valid.
        g = subprocess.run(["nvidia-smi", "--query-gpu=memory.used", "--format=csv,noheader,nounits"], capture_output=True, text=True, timeout=8)
        vals = []
        for line in (g.stdout or "").splitlines():
            try: vals.append(int(float(re.sub(r"[^0-9.]", "", line) or 0)))
            except Exception: pass
        fallback = max(vals) if vals else 0
        return fallback, {}, False
    except Exception:
        return 0, {}, False

def _managed_pid_tree(name):
    root_pid = MANAGER.get_pid(name)
    if not root_pid: return set()
    pids = {int(root_pid)}
    if psutil is not None:
        try: pids.update(int(x.pid) for x in psutil.Process(int(root_pid)).children(recursive=True))
        except Exception: pass
    return pids

def verify_tts_gpu_runtime(name: str, wait_seconds: float = 20.0, min_vram_mb: int = 256):
    """Hard runtime gate: CUDA environment + real NVIDIA VRAM owned by TTS process tree."""
    info = ENGINE_INFO.get(name)
    if not info: return False, "Engine TTS không hợp lệ."
    py = venv_python(info["venv"])
    cuda_ok, cuda_detail = _cuda_check_python(py)
    if not cuda_ok: return False, f"CUDA environment FAIL: {cuda_detail}"
    if not MANAGER.running(name): return False, f"TTS server `{name}` chưa chạy."
    deadline = time.time() + max(0.0, float(wait_seconds)); last_vram = 0; attributed = False
    while time.time() <= deadline:
        pids = _managed_pid_tree(name); last_vram, _, attributed = _gpu_memory_by_pids(pids)
        if last_vram >= int(min_vram_mb):
            if attributed:
                detail = f"CUDA READY · {info['short']} · VRAM {last_vram} MB · PID tree={sorted(pids)}"
            else:
                detail = f"CUDA READY · {info['short']} · NVIDIA VRAM {last_vram} MB · WDDM không trả PID attribution"
            return True, detail
        if _master_is_stopped() or SCRIPT_STOP_EVENT.is_set(): return False, "MASTER đã dừng trong lúc chờ TTS GPU runtime."
        time.sleep(0.5)
    return False, f"TTS GPU RUNTIME FAIL: server `{name}` health nhưng NVIDIA VRAM chỉ {last_vram} MB (< {int(min_vram_mb)} MB)."

def _tts_gpu_snapshot(name: str):
    """Best-effort NVIDIA telemetry for the managed TTS server.

    This is diagnostic only. Windows/WDDM may report very low instantaneous
    utilization for short TTS kernels, and nvidia-smi cannot prove which model
    kernel owns that utilization. Never use utilization as the hard gate.
    """
    if not shutil.which("nvidia-smi"):
        return {}
    try:
        r=subprocess.run([
            "nvidia-smi",
            "--query-gpu=utilization.gpu,memory.used,memory.total",
            "--format=csv,noheader,nounits"
        ],capture_output=True,text=True,timeout=5)
        line=next((x.strip() for x in (r.stdout or "").splitlines() if x.strip()),"")
        parts=[x.strip() for x in line.split(",")]
        if len(parts)>=3:
            return {"gpu_util_pct":int(float(parts[0])),"vram_used_mb":int(float(parts[1])),"vram_total_mb":int(float(parts[2]))}
    except Exception:
        pass
    return {}


def master_voice_gpu_gate(name: str):
    workflow_cmd_log("VOICE", "GPU_RUNTIME_GATE_START", engine=name, pct=0)
    ok, detail = verify_tts_gpu_runtime(name)
    if not ok:
        workflow_cmd_log("VOICE", "GPU_RUNTIME_GATE_FAIL", engine=name, error=detail, level="ERROR")
        raise RuntimeError("⛔ VOICE GPU GATE FAIL — " + detail)
    snap=_tts_gpu_snapshot(name)
    if snap:
        detail += f" · GPU util snapshot={snap['gpu_util_pct']}% · VRAM={snap['vram_used_mb']}/{snap['vram_total_mb']} MB"
    workflow_cmd_log("VOICE", "GPU_RUNTIME_GATE_OK", engine=name, detail=detail, gpu_util=snap.get("gpu_util_pct") if snap else None, vram_mb=snap.get("vram_used_mb") if snap else None, pct=1)
    return detail


def gpu_report():
    lines=[]; smi=shutil.which("nvidia-smi")
    if smi:
        try:
            r=subprocess.run([smi,"--query-gpu=name,driver_version,memory.total,memory.used,memory.free","--format=csv,noheader,nounits"],capture_output=True,text=True,timeout=15); lines.append("🟢 GPU 1: "+((r.stdout or "").strip() or "không có dữ liệu"))
        except Exception as exc: lines.append(f"🔴 nvidia-smi lỗi: {exc}")
    else: lines.append("🔴 Không tìm thấy nvidia-smi.")
    checks=[("Main Python / PyTorch CUDA",Path(sys.executable))]
    checks += [(ENGINE_INFO[n]["short"]+" CUDA",venv_python(ENGINE_INFO[n]["venv"])) for n in ("chatterbox","omnivoice","vieneu","cloneprep") if n in ENGINE_INFO]
    for label,py in checks:
        try: ok,detail=_cuda_check_python(py); detail=detail.replace("\n"," | ")
        except Exception as exc: ok=False; detail=str(exc)
        lines.append(f"{'🟢' if ok else '🔴'} {label}: {'OK' if ok else 'LỖI'} — {detail}")
    return "\n".join(lines)

def save_selected_voice(v):
    SETTINGS["selected_voice"] = normalize_voice_value(v or "")
    try:
        data=load_workflow_profiles(); active=current_workflow_profile()
        if active: data.setdefault(active,{})["selected_voice"]=SETTINGS["selected_voice"]; save_workflow_profiles(data)
    except Exception: save_settings()
    return "✓ Đã lưu voice đang chọn cho lần sau."

def save_selected_voice_and_engine(v,engine):
    lang, requested, resolved, voice = _canonical_voice_for_engine(
        SETTINGS.get("selected_language", "auto"), engine, v, SETTINGS.get("workflow_script", "")
    )
    SETTINGS["selected_language"] = lang if SETTINGS.get("selected_language", "auto") == "auto" else SETTINGS.get("selected_language")
    SETTINGS["selected_voice"] = normalize_voice_value(voice or "")
    SETTINGS["selected_engine"] = requested
    try:
        data=load_workflow_profiles(); active=current_workflow_profile()
        if active:
            cfg=data.setdefault(active,{})
            cfg["selected_voice"]=SETTINGS["selected_voice"]
            cfg["voice"]=SETTINGS["selected_voice"]
            cfg["selected_engine"]=SETTINGS["selected_engine"]
            cfg["engine"]=SETTINGS["selected_engine"]
            save_workflow_profiles(data)
    except Exception:
        pass
    save_settings(); info=ENGINE_INFO.get(resolved,{})
    model=info.get("hf_model") or info.get("model") or "—"
    return f"🟢 Đã chọn Voice `{voice or '(auto)'}` · Server `{info.get('short',resolved)}` · Engine `{requested}` · Model `{model}`."

def test_gemini_key(key: str):
    key=(key or "").strip()
    if not key: return "✕ Chưa nhập API Key."
    try:
        from google import genai
        from google.genai import types
        client=genai.Client(api_key=key, http_options=types.HttpOptions(timeout=30_000))
        result=client.models.generate_content(
            model=GEMINI_MODEL, contents="Reply only OK.",
            config=types.GenerateContentConfig(
                automatic_function_calling=types.AutomaticFunctionCallingConfig(disable=True)
            ),
        )
        value=(getattr(result,"text",None) or "OK").strip()
        return f"✓ Gemini API OK · Model `{GEMINI_MODEL}` — " + value[:60]
    except Exception as exc: return "✕ Gemini API lỗi: "+str(exc)[:1600]

def voice_scene_short_text(text: str, words: int = 7) -> str:
    clean = re.sub(r"\s+", " ", (text or "").strip())
    if not clean:
        return ""
    tokens = clean.split(" ")
    preview = " ".join(tokens[:words])
    return preview + ("…" if len(tokens) > words else "")


def voice_save_root(project: str = "") -> Path:
    """Canonical Project audio root inside 02_MEDIA; never create a legacy root."""
    root = _project_audio_dir(project_dir(project))
    if PROJECT_CONNECTED:
        root.mkdir(parents=True, exist_ok=True)
    return root


