def voice_scene_manager_rows(project: str):
    if isinstance(project, dict):
        project = project.get("value") or project.get("name") or project.get("label") or ""
    scenes = load_manifest(project)
    root = project_dir(project)
    timings = read_json(_project_media_dir(root) / "Âm thanh" / "scene_timings.json", []) or []
    timing_map = {x.get("scene_id"): x for x in timings}
    rows, choices, files = [], [], []
    scene_dir = voice_scene_dir(project)
    legacy_dir = _project_media_dir(root) / "Âm thanh" / "Cảnh"
    for s in scenes:
        sid = s["scene_id"]
        audio = scene_dir / f"{sid}.wav"
        legacy = legacy_dir / f"{sid}.wav"
        if not audio.exists() and legacy.exists():
            try: shutil.copy2(legacy, audio)
            except Exception: pass
        exists = audio.exists()
        t = timing_map.get(sid, {})
        duration = float(t.get("duration", 0) or 0)
        status = f"✓ Đã tạo • {duration:.2f}s" if exists else "⏳ Chưa tạo"
        rows.append([voice_scene_short_text(s.get("text", "")), status])
        if exists:
            files.append(str(audio)); choices.append((sid, sid))
    return rows, choices, files




