PROJECT_STATUS_META = {
    'idea': ('🔴', 'Đang lên ý tưởng', '#ef4444'),
    'building': ('🟡', 'Đang dựng', '#eab308'),
    'done': ('🟢', 'Đã hoàn thành', '#22c55e'),
}


def _project_archive_meta(root: Path) -> dict:
    meta = read_json(project_archive_file(root.name), {}) or {}
    if not isinstance(meta, dict): meta = {}
    if not meta.get('status'):
        has_final = (_project_export_dir(root) / 'QC' / 'final_qc.txt').exists() or (_project_export_dir(root) / 'Dòng thời gian' / 'timeline.json').exists() and (_project_media_dir(root) / 'Âm thanh' / 'Voice Full' / 'Voice_Full.wav').exists()
        has_work = (_project_content_dir(root) / 'Kịch bản' / 'script.txt').exists() or (_project_content_dir(root) / 'Cảnh' / 'manifest.json').exists()
        meta['status'] = 'done' if has_final else ('building' if has_work else 'idea')
    meta.setdefault('done', meta.get('status') == 'done')
    meta.setdefault('note', '')
    meta.setdefault('publish_date', '')
    meta.setdefault('next_date', '')
    meta.setdefault('pipeline_completed', bool(meta.get('done') and meta.get('status') == 'done'))
    meta.setdefault('completed_at', '')
    meta.setdefault('completed_at_display', '')
    meta.setdefault('processing_time', str(meta.get('last_master_elapsed_display') or ''))
    meta.setdefault('updated', datetime.now().isoformat())
    return meta


def _project_archive_roots():
    roots = []
    for raw in [str(PROJECTS), str(SETTINGS.get('project_output_dir') or ''), str(SETTINGS.get('selected_project_path') or '')]:
        if not raw: continue
        p = Path(raw).expanduser()
        if p.exists() and p.is_dir(): roots.append(p.resolve())
    return list(dict.fromkeys(roots))


def _is_canonical_project_root(pth: Path) -> bool:
    """Recognize the real Project root, including the canonical 01/02/03 layout."""
    try:
        return bool(
            pth.is_dir() and (
                (pth / '01_NỘI_DUNG').is_dir() and (pth / '02_MEDIA').is_dir() and (pth / '03_XUẤT_BẢN').is_dir()
                or (pth / 'Cảnh').is_dir()
                or (pth / 'Kịch bản').is_dir()
                or (pth / 'project_meta.json').is_file()
            )
        )
    except Exception:
        return False


def project_archive_list():
    """List actual Project roots, never 01_NỘI_DUNG/02_MEDIA as fake projects."""
    found = {}
    selected = safe_name(SETTINGS.get('selected_project',''))
    selected_path = str(SETTINGS.get('selected_project_path','') or '').strip()
    for base in _project_archive_roots():
        try:
            # If this is the connected Project itself, use it directly.
            # This is the important path for the canonical Downloads/Project_xxx layout.
            if _is_canonical_project_root(base) and (not selected or safe_name(base.name) == selected or str(base.resolve()) == str(Path(selected_path).expanduser().resolve()) if selected_path else True):
                found[str(base.resolve()).lower()] = base
                continue
            children = list(base.iterdir())
        except Exception:
            continue
        for pth in children:
            try:
                if not pth.is_dir() or pth.name.startswith('.') or pth.name in {'__pycache__'}:
                    continue
                if not _is_canonical_project_root(pth):
                    continue
                found[str(pth.resolve()).lower()] = pth
            except Exception:
                continue
    return sorted(found.values(), key=lambda p: p.name.lower())


def project_archive_html():
    projects = project_archive_list()
    rows = []
    for root in projects:
        meta = _project_archive_meta(root)
        key = str(meta.get('status') or 'idea')
        icon, label, color = PROJECT_STATUS_META.get(key, PROJECT_STATUS_META['idea'])
        checked = 'checked' if bool(meta.get('done')) or key == 'done' else ''
        rows.append(
            '<tr>'
            f'<td><input type="checkbox" {checked} disabled></td>'
            f'<td><b>{html.escape(root.name)}</b></td>'
            f'<td><span style="display:inline-block;padding:4px 9px;border-radius:999px;background:{color}22;color:{color};font-weight:800">{icon} {html.escape(label)}</span></td>'
            f'<td>{html.escape(str(meta.get("processing_time") or meta.get("last_master_elapsed_display") or "—"))}</td>'
            f'<td>{html.escape(str(meta.get("publish_date") or "—"))}</td>'
            f'<td>{html.escape(str(meta.get("next_date") or "—"))}</td>'
            f'<td>{html.escape(str(meta.get("note") or "—"))}</td>'
            '</tr>'
        )
    if not rows:
        return '<div style="padding:18px;border-radius:12px;background:rgba(128,128,128,.08)">📭 Chưa tìm thấy Project workflow trong các thư mục đã cấu hình.</div>'
    return ('<div style="overflow:auto"><table style="width:100%;border-collapse:collapse">'
            '<thead><tr><th>☑</th><th>Project</th><th>Trạng thái</th><th>Thời Gian Xử Lý</th><th>Ngày xuất bản</th><th>Lịch tiếp</th><th>Note</th></tr></thead>'
            '<tbody>' + ''.join(rows) + '</tbody></table></div>')


def project_archive_load(project: str):
    p = safe_name(project or '')
    if not p: return 'idea', False, '', '', '', project_archive_html()
    meta = _project_archive_meta(project_dir(p))
    status = str(meta.get('status') or 'idea')
    if status not in PROJECT_STATUS_META: status = 'idea'
    return status, bool(meta.get('done') or status == 'done'), str(meta.get('note') or ''), str(meta.get('publish_date') or ''), str(meta.get('next_date') or ''), project_archive_html()


def _mark_project_pipeline_complete(project: str):
    """Auto-mark Archive done only when the full QC artifact set is present."""
    project = safe_name(project or '')
    if not project:
        return False, ''
    root = project_dir(project)
    if not root.exists():
        return False, ''
    try:
        expected = _qc_expected_files(project)
    except Exception:
        return False, ''
    final_qc = (_project_export_dir(root) / 'QC' / 'final_qc.txt')
    if not final_qc.exists() or not all(bool(v) for v in expected.values()):
        workflow_cmd_log('PROJECT_ARCHIVE', 'AUTO_COMPLETE_WAITING_ARTIFACTS', project=project, missing=[k for k,v in expected.items() if not v], final_qc=final_qc.exists(), level='INFO')
        return False, ''
    meta = _project_archive_meta(root)
    latest_processing = str(meta.get('last_master_elapsed_display') or meta.get('processing_time') or '')
    if meta.get('pipeline_completed') and meta.get('completed_at'):
        if latest_processing and meta.get('processing_time') != latest_processing:
            meta['processing_time'] = latest_processing
            meta['updated'] = vietnam_now().isoformat()
            write_json(project_archive_file(root.name), meta)
        return True, str(meta.get('completed_at_display') or meta.get('completed_at'))
    completed = vietnam_now()
    display = vietnam_time_display(completed)
    meta.update({'status':'done','done':True,'pipeline_completed':True,'completed_at':completed.isoformat(),'completed_at_display':display,'processing_time':latest_processing,'updated':completed.isoformat()})
    write_json(project_archive_file(root.name), meta)
    print(f'[VHƯNG PRO MAX {display}] PROJECT COMPLETE | project={project} | archive=done', flush=True)
    workflow_cmd_log('PROJECT_ARCHIVE', 'AUTO_COMPLETE', project=project, completed_at=display)
    return True, display


def project_archive_save(project, status, done, note, publish_date, next_date):
    project = safe_name(project or '')
    if not project: return '⚠ Chưa chọn Project.', project_archive_html()
    root = project_dir(project)
    root.mkdir(parents=True, exist_ok=True)
    status = status if status in PROJECT_STATUS_META else 'idea'
    done = bool(done) or status == 'done'
    if done: status = 'done'
    meta = _project_archive_meta(root)
    meta.update({'status': status, 'done': done, 'note': str(note or '').strip(), 'publish_date': str(publish_date or '').strip(), 'next_date': str(next_date or '').strip(), 'updated': datetime.now().isoformat()})
    if done:
        meta['pipeline_completed'] = True
        meta.setdefault('completed_at', vietnam_now().isoformat())
        meta.setdefault('completed_at_display', vietnam_time_display())
    write_json(project_archive_file(root.name), meta)
    return f"✅ Đã lưu Archive: **{project}** · {PROJECT_STATUS_META[status][0]} {PROJECT_STATUS_META[status][1]}", project_archive_html()


