def save_settings_ui(lang, appearance, accent, key, max_vram):
    """Persist UI settings without erasing a Gemini key on a Gradio rerender."""
    try:
        fallback_vram = int(SETTINGS.get("max_vram_percent", 82) or 82)
    except (TypeError, ValueError):
        fallback_vram = 82
    try:
        vram = fallback_vram if max_vram in (None, "") else int(max_vram)
    except (TypeError, ValueError):
        vram = fallback_vram
    vram = max(50, min(95, vram))
    current_key = str(SETTINGS.get("gemini_api_key", "") or "").strip()
    gemini_key = current_key if key is None else str(key).strip()
    SETTINGS.update({
        "language": lang if lang in ("vi", "en") else SETTINGS.get("language", "vi"),
        "appearance": appearance if appearance in ("dark", "light", "system") else SETTINGS.get("appearance", "dark"),
        "accent": accent if accent in ACCENTS else SETTINGS.get("accent", "teal"),
        "gemini_api_key": gemini_key,
        "max_vram_percent": vram,
    })
    save_settings()
    key_state = (f"Gemini API Key: ✓ đã lưu · `data/config/settings.json` + `data/config/gemini_api_key.txt`"
                 if gemini_key else "Gemini API Key: chưa có")
    return (f"✓ Đã lưu cài đặt · {key_state} · **Build {GEMINI_KEY_UX_BUILD}**. Đang tải lại UI..."
            if SETTINGS["language"] == "vi" else f"✓ Saved · {key_state}. Reloading UI...")


def save_gemini_key_ui(key):
    """Save or explicitly delete the Gemini credential from the dedicated UX path."""
    key = "" if key is None else str(key).strip()
    if not key:
        previous = str(SETTINGS.get("gemini_api_key") or "").strip()
        if previous:
            save_settings._last_saved_key = previous
        SETTINGS["gemini_api_key"] = ""
        save_settings()
        return "🟢 **Đã xóa Gemini API Key khỏi máy.** `settings.json`, `gemini_api_key.txt` và key store đã được đồng bộ."
    SETTINGS["gemini_api_key"] = key
    save_settings()
    ok_settings = False
    ok_store = False
    try:
        saved = read_json(SETTINGS_FILE, {})
        ok_settings = str(saved.get("gemini_api_key") or "").strip() == key if isinstance(saved, dict) else False
    except Exception:
        pass
    try:
        store = read_json(BASE / "gemini_keys.json", {})
        ok_store = key in (store.get("keys", []) if isinstance(store, dict) else [])
    except Exception:
        pass
    if ok_settings and ok_store:
        try:
            key_count = len(_load_gemini_keys())
        except Exception:
            key_count = 1
        return (f"🟢 **Gemini API SẴN SÀNG.** `{key_count} key` đã lưu · "
                "`settings.json` ✓ · `gemini_keys.json` ✓ · `gemini_api_key.txt` ✓ "
                "· **Build GEMINI-KEY-UX-V4**")
    return (f"🟠 Đã ghi key nhưng chưa xác minh đủ: settings.json={ok_settings}, "
            f"gemini_keys.json={ok_store}. **Build GEMINI-KEY-UX-V3**")


