def _backup_original_before_clean(project):
    root = project_dir(project); src = _project_media_dir(root) / "Hình ảnh"; dst = _project_export_dir(root) / "QC" / "archive" / "original_before_clean"
    dst.mkdir(parents=True, exist_ok=True)
    copied = []
    for p in sorted(src.iterdir() if src.exists() else [], key=lambda x:x.name.lower()):
        if not p.is_file() or p.suffix.lower() not in SUPPORTED_IMAGE:
            continue
        q = dst / p.name
        if not q.exists():
            shutil.copy2(p, q)
        copied.append(str(q))
    return copied


def _build_capcut_scene_media(project: str):
    """Create silent per-scene MP4s whose durations exactly follow Voice Scene timing."""
    root = project_dir(project)
    media = _project_export_dir(root) / "CapCut" / "timeline_media"
    media.mkdir(parents=True, exist_ok=True)
    timeline = read_json(_project_export_dir(root) / "Dòng thời gian" / "timeline.json", []) or build_timeline(project)
    try:
        import imageio_ffmpeg
        ffmpeg = imageio_ffmpeg.get_ffmpeg_exe()
    except Exception:
        ffmpeg = shutil.which("ffmpeg")
    if not ffmpeg:
        return []
    out = []
    for item in timeline:
        sid = str(item.get("scene_id", ""))
        image = Path(item.get("image", ""))
        duration = max(0.1, float(item.get("duration", 5)))
        if not image.exists():
            continue
        target = media / f"{sid}.mp4"
        cmd = [ffmpeg, "-y", "-loop", "1", "-i", str(image), "-t", f"{duration:.3f}",
               "-r", "30", "-an", "-c:v", "libx264", "-pix_fmt", "yuv420p", str(target)]
        try:
            subprocess.run(cmd, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, check=True)
            out.append(target)
        except Exception:
            pass
    return out


def _chunk_checkpoint_write(project, chunk_id, scenes, completed, failed):
    root = _project_export_dir(project_dir(project)) / "QC" / "Checkpoints"
    root.mkdir(parents=True, exist_ok=True)
    path = root / "chunks.json"
    obj = read_json(path, {}) or {}
    obj[str(chunk_id)] = {"chunk_id": str(chunk_id), "scene_ids": [str(s.get("scene_id")) for s in scenes], "completed": list(completed), "failed": list(failed), "updated_at": vietnam_now().isoformat()}
    save_json(path, obj)


def _clean_max_vip_hud(pct:int,detail:str=""):
    pct=max(0,min(100,int(pct))); filled=int(round(28*pct/100)); bar='█'*filled+'░'*(28-filled)
    return f"<div style='padding:12px 14px;border-radius:12px;background:rgba(127,127,127,.08);border:1px solid rgba(127,127,127,.20);font-family:ui-monospace,SFMono-Regular,Consolas,monospace'><b>🧼 CLEAN MAX VIP</b><div style='margin:7px 0'>[{bar}] <b>{pct}%</b></div><div>{html.escape(str(detail or '')[:900])}</div></div>"


def _cleanup_unused_empty_project_dirs(root: Path):
    """Remove only empty legacy folders from older LocalAIStudio versions."""
    for rel in ("script", "prompts", "timeline", "character_bible", "Âm thanh/scenes"):
        p = root / rel
        try:
            if p.is_dir() and not any(p.iterdir()):
                p.rmdir()
        except Exception:
            pass


