def _master_cmd(message: str, level: str = "INFO") -> None:
    """CMD console ngắn gọn, tiếng Việt; không in % giả hoặc log kỹ thuật dư thừa."""
    try:
        raw = re.sub(r"\s+", " ", str(message or "").strip())
        if not raw:
            return
        # Bỏ các cụm kỹ thuật không có giá trị cho người vận hành.
        raw = re.sub(r"\b(focus|focused|focus on)\b", "đang xử lý", raw, flags=re.I)
        if re.search(r"hot cache|session_hot|batch_session|model cache|scene timing|queue wait|gpu execution|bootstrap_seconds", raw, re.I):
            return
        translations = [
            ("ComfyUI DONE", "ComfyUI xong"),
            ("ComfyUI queue", "ComfyUI bắt đầu"),
            ("ComfyUI API READY", "ComfyUI sẵn sàng"),
            ("Z-Image-Turbo Int8/FP8 READY", "Z-Image-Turbo sẵn sàng"),
            ("START —", "Bắt đầu —"),
            ("START", "Bắt đầu"),
            ("FINISHED", "Đã xong"),
            ("DONE", "Đã xong"),
            ("READY", "Sẵn sàng"),
            ("VERIFY", "Kiểm tra"),
            ("FINAL VERIFY FAIL", "Kiểm tra cuối lỗi"),
            ("ZIMAGE_SCENE_GENERATE_FAIL", "Render ảnh lỗi"),
            ("ZIMAGE_FINAL_VERIFY_FAIL", "Ảnh cuối kiểm tra lỗi"),
            ("ZIMAGE_COMPLETE_QC_UNLOCK", "Ảnh đã đủ, mở QC"),
            ("ZIMAGE_NOT_COMPLETED", "Ảnh chưa hoàn tất"),
            ("QC_BLOCKED_ZIMAGE_GATE", "QC bị chặn: ảnh chưa xác nhận đủ"),
            ("RESUME_SKIP_ZIMAGE", "Đã có ảnh hợp lệ, bỏ qua render"),
            ("CHUNK_START", "Bắt đầu nhóm ảnh"),
            ("CHUNK_QC_CHECKPOINT", "Đã lưu nhóm ảnh"),
            ("MASTER START", "Workflow bắt đầu"),
            ("MASTER FINISHED", "Workflow kết thúc"),
            ("Reference upload lỗi, tiếp tục text-to-image", "Ảnh tham chiếu lỗi, tạo từ prompt"),
            ("Reference upload lỗi, tiếp tục", "Ảnh tham chiếu lỗi, tiếp tục"),
            ("MODEL PATHS READY", "Model sẵn sàng"),
            ("MODEL INDEX OK", "Model sẵn sàng"),
            ("API READY", "ComfyUI sẵn sàng"),
            ("UI BROWSER READY", "Đã mở ComfyUI"),
            ("MAX GPU PROFILE ACTIVE", "GPU sẵn sàng"),
            ("AUTHORITATIVE GRAPH QUEUED", "Đã xếp hàng tạo ảnh"),
            ("SCENE TIMING", "Đã hoàn tất cảnh"),
            ("Z-IMAGE MODEL BOOTSTRAP FAIL", "Z-Image khởi động lỗi"),
            ("ComfyUI Portable thoát sớm", "ComfyUI khởi động lỗi"),
            ("completion marker missing", ""),
            ("auto_topic_classified", "Đã xác định chủ đề"),
            ("GEMINI_B1_B2_COMPLETE", "Gemini hoàn tất B1+B2"),
            ("GEMINI_B1_B2_SINGLE_CHAIN_START", "Gemini bắt đầu B1+B2"),
            ("GEMINI_B1_B2_NOT_COMPLETE", "Gemini chưa hoàn tất B1+B2"),
            ("TAB_IMAGES_OPEN", "Mở Hình ảnh"),
            ("SKILL_STAGE3_READY", "Đã chuẩn bị tạo hình"),
        ]
        msg=raw
        for a,b in translations:
            msg=msg.replace(a,b)
        # Nếu là lỗi Python dài, chỉ lấy phần cuối có ích.
        if len(msg)>180:
            msg=msg[:177].rstrip()+"…"
        upper=msg.upper()
        level_u=str(level or "INFO").upper()
        is_error=level_u in {"ERROR","WARN","FAIL","FAILED"} or any(x in upper for x in (" LỖI", "FAIL", "ERROR", "TIMEOUT", "THẤT BẠI"))
        # Chỉ in mốc vận hành thực sự hữu ích.
        useful=is_error or any(x in upper for x in ("BẮT ĐẦU", "ĐÃ XONG", "ĐÃ TẠO XONG", "SẴN SÀNG", "LỖI", "DỪNG", "MỞ QC", "RENDER ẢNH"))
        if not useful:
            return
        # Không in % trong CMD. Tiến độ render hiển thị bằng x/y bước hoặc Scene x/y.
        msg=re.sub(r"\s*\d{1,3}%", "", msg).strip(" ·-")
        sig=msg
        now=time.monotonic()
        with _COMFY_CONSOLE_LOCK:
            last=_COMFY_CONSOLE_LAST.get(sig,0.0)
            if not is_error and now-last<1.2:
                return
            _COMFY_CONSOLE_LAST[sig]=now
        stamp=vietnam_now().strftime('%H:%M:%S')
        stage = "Z-IMAGE" if "Z-IMAGE" in upper or "COMFYUI" in upper or "RENDER ẢNH" in upper else "MASTER"
        print(f"[{stamp}] [{stage}] {msg}", flush=True)
    except Exception:
        pass


def _master_full_voice_progress_ui(project, language, engine, voice, script, fresh=False):
    # Native sync-generator callback: exactly 8 outputs on every yield.
    # Do not pass this function through the async bridge because older bridge
    # versions returned the generator itself as one output.
    if not _master_scene_gate_ok(project):
        msg = "⛔ Voice Full bị khóa — Gemini Scene Split chưa VERIFY. Workflow dừng tại Scene."
        workflow_cmd_log("MASTER", "VOICE_BLOCKED_SCENE_GATE", project=project)
        yield (
            voice_live_loader("", 0, msg, False), msg, None, None, [], "", "",
            _workflow_progress_card(msg, 100, "gemini")
        )
        return
    if _master_is_stopped():
        stop_msg = "⏹ MASTER đã dừng — bỏ qua bước Voice Full."
        yield (
            voice_live_loader("", 0, stop_msg, False),
            stop_msg,
            None,
            None,
            [],
            "",
            "",
            _workflow_progress_card(stop_msg, 100, "voice"),
        )
        return
    voice_ok, master_voice, voice_count = _project_voice_checkpoint(project)
    if voice_ok and master_voice and not fresh:
        msg = f"♻ RESUME — Voice Full đã có sẵn và VERIFY đủ {voice_count}/{voice_count} Scene + Voice_Full.wav. Bỏ qua tạo Voice."
        workflow_cmd_log("MASTER", "RESUME_SKIP_VOICE", project=project, scene_count=voice_count)
        yield (
            voice_live_loader("Voice Full", 100, msg, True),
            msg,
            _gradio_safe_file(master_voice),
            _gradio_safe_file(master_voice),
            [],
            "",
            "",
            _workflow_progress_card(msg, 100, "voice"),
        )
        return
    if fresh:
        workflow_cmd_log("MASTER", "RUN_FAST_FRESH_VOICE", project=project)
    workflow_cmd_log('B2', 'START — Voice Full')
    actual_lang = _effective_voice_language(language, script or SETTINGS.get("workflow_script", "") or "")
    requested_engine = str(engine or "auto")
    resolved_engine = resolve_engine(actual_lang, requested_engine)
    effective_voice = configured_voice_value(actual_lang, requested_engine, voice)
    voice_label = voice_choice_label(actual_lang, requested_engine, effective_voice)
    workflow_cmd_log("VOICE", "START", project=project, language=actual_lang, engine=requested_engine, resolved_engine=resolved_engine, voice=effective_voice, voice_label=voice_label, profile=SETTINGS.get("workflow_profile", ""), source="live_voice_selection")
    workflow_cmd_log("VOICE", "VOICE_SELECTED", project=project, voice=effective_voice, voice_label=voice_label, source="workflow_profile")
    # Voice runs serially after Environment/RAIW CUDA work. The TTS server
    # owns its GPU memory while generating; on an unexpected failure/stop,
    # release it here so a later stage cannot inherit a full VRAM allocation.
    try:
        for item in full_voice_generator(project, language, engine, effective_voice, script, stop_event=SCRIPT_STOP_EVENT):
            row = list(item) if isinstance(item, (tuple, list)) else []
            while len(row) < 7:
                row.append(None if len(row) in (2, 3) else [])
            row = row[:7]
            status = str(row[1] or '')
            pct = _safe_int(row[0], 0, 0, 100)
            row[0] = gr.update(value=row[0], visible=True)
            yield (*row, _workflow_progress_card(status, pct, 'voice'))
    except BaseException as exc:
        workflow_cmd_log("VOICE", "FAIL_SAFE_VRAM_RELEASE", project=project, engine=resolved_engine, error=str(exc)[:800])
        try:
            release_voice_vram(actual_lang, resolved_engine)
        except Exception:
            pass
        _master_vram_cleanup("voice_failure")
        raise
    workflow_cmd_log("VOICE", "END", project=project, voice=effective_voice, voice_label=voice_label)


def _master_gradio_files(items):
    out=[]
    for item in items or []:
        try:
            p=Path(item)
            if p.exists() and p.is_file(): out.append(str(p.resolve()))
        except Exception: pass
    return out


